/* テキストの「さらに深く」拡充(担当:高校数学 m1_expand〜m_h7 の26単元) */
(function (L) {
  function add(id, o) {
    var x = L[id]; if (!x) return;
    ['secs', 'drill', 'faq'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); });
  }

  add('m1_expand', {
    secs: [
      { h: 'さらに深く:対称式・交代式は「形」から因数が見える', t: '文字が3つある式の因数分解では、式の【形】に注目すると、計算する前に答えの見当がつくことがあります。\n【対称式】は、どの2文字を入れかえても変わらない式です。a + b + c や ab + bc + ca、a³ + b³ + c³ − 3abc などがそうです。\n【交代式】は、どの2文字を入れかえても、符号だけが逆になる式です。代表は (a − b)(b − c)(c − a) です。a と b を入れかえると (b − a)(a − c)(c − b) となり、3つのかっこがどれも符号を変えるので、全体ではもとの式の (−1)³ = −1 倍になります。\nここで大事な事実があります。交代式は、a = b とおくと必ず 0 になります。a = b のときは、a と b を入れかえても式の見た目も値も変わりません。ところが交代式なので、入れかえると符号が逆になるはずです。「値 = −値」となる数は 0 しかありません。a = b で 0 になるということは、因数定理の考え方で【a − b を因数にもつ】ということです。同じように b − c、c − a も因数です。\n例:a²(b − c) + b²(c − a) + c²(a − b) は、a と b を入れかえると符号が逆になる交代式です。全体は3次式なので、(a − b)(b − c)(c − a)(3次)に定数 k をかけた形になるはずです。a² b の係数を比べると、左辺は +1、(a − b)(b − c)(c − a) を展開した式では −1 なので、k = −1 と決まります。\nこのように、【交代式 = (a − b)(b − c)(c − a) × 対称式】という形を知っていると、どの文字で整理するか迷ったときの道しるべになります。もちろん、答えの見当がついたら、「最も次数の低い文字で整理する」という基本の方法でも確かめておきます。', key: '交代式は (a − b)(b − c)(c − a) を因数にもつ。式の「入れかえに対する性質」を見ると、答えの形が先に予想できる。', ex: [{ q: 'a³ + b³ + c³ − 3abc を因数分解しよう。', hint: 'a³ + b³ = (a + b)³ − 3ab(a + b) を使い、a + b をひとかたまりと見る。', steps: ['a³ + b³ をそのまま扱うと進まないので、(a + b)³ − 3ab(a + b) と書きかえます。こうすると a + b というかたまりが見えてきます。', '式全体は (a + b)³ + c³ − 3ab(a + b) − 3abc。前の2つは A³ + c³(A = a + b)の形なので、(A + c)(A² − Ac + c²) と因数分解できます。', '後ろの2つは −3ab(a + b + c) と共通因数 a + b + c でくくれます。前の部分も A + c = a + b + c を因数にもつので、全体を a + b + c でくくれます。', 'くくると (a + b + c){(a + b)² − (a + b)c + c² − 3ab}。中かっこの中を展開して整理すると a² + b² + c² − ab − bc − ca になります。'], a: '(a + b + c)(a² + b² + c² − ab − bc − ca)', check: 'a = 1、b = 2、c = 3 を代入すると、左辺 1 + 8 + 27 − 18 = 18、右辺 6 × (14 − 11) = 18 で一致します。この結果から、a + b + c = 0 のときは a³ + b³ + c³ = 3abc が成り立つことも分かります。' }] },
      { h: '実戦演習:1次式の積に分解できる条件を求める', t: '「x と y の2次式が、x、y の1次式の積に因数分解できるような定数の値を求めよ」という問題は、入試の定番です。\n戦略は、【2次の部分だけを先に因数分解する】ことです。x² + xy − 2y² のような2次の項だけの部分は、ふつうの因数分解で (x + 2y)(x − y) と分かれます。すると、全体は (x + 2y + p)(x − y + q) の形になるはずなので、p、q を未知数として展開し、係数を比べます。\n落とし穴は2つです。1つは、条件の式が3つ(x の係数、y の係数、定数項)出てくるのに未知数が p、q、a の3つあることを見落とし、途中で止まってしまうこと。もう1つは、2次方程式から出た2つの解の片方だけを答えてしまうことです。', key: '2次の項だけを先に因数分解し、残りを未知数 p、q で置く。出てきた解はすべて確かめて答える。', ex: [{ q: 'x² + xy − 2y² + ax + 7y − 3 が x、y の1次式の積に因数分解できるような定数 a の値を求めよう。', hint: 'x² + xy − 2y² = (x + 2y)(x − y)。全体を (x + 2y + p)(x − y + q) とおく。', steps: ['2次の項 x² + xy − 2y² だけを因数分解すると (x + 2y)(x − y) です。全体が1次式の積になるなら、それぞれのかっこに定数を足した (x + 2y + p)(x − y + q) の形しかありえません。', '展開すると x² + xy − 2y² + (p + q)x + (2q − p)y + pq。もとの式と係数を比べると、p + q = a、2q − p = 7、pq = −3 です。', '2つ目の式から p = 2q − 7。3つ目に代入すると (2q − 7)q = −3、つまり 2q² − 7q + 3 = 0 となり、(2q − 1)(q − 3) = 0 から q = 3 または q = 1/2 です。', 'q = 3 のとき p = −1 で a = 2。q = 1/2 のとき p = −6 で a = −11/2。どちらも3つの式をすべて満たします。'], a: 'a = 2、−11/2', check: 'a = 2 のとき (x + 2y − 1)(x − y + 3)、a = −11/2 のとき (x + 2y − 6)(x − y + 1/2) となり、展開するともとの式にもどります。別解として、x について整理し「x の2次方程式の判別式が y の式として完全平方になる」条件から求めることもできます。' }] }
    ],
    drill: [
      { lv: 2, q: 'x² − y² + 4y − 4 を因数分解しよう。', a: '(x + y − 2)(x − y + 2)', exp: 'y をふくむ項 −y² + 4y − 4 をまとめると −(y² − 4y + 4) = −(y − 2)² です。すると式は x² − (y − 2)² となり、A² − B² の形になります。(x + (y − 2))(x − (y − 2)) = (x + y − 2)(x − y + 2) です。まちがえやすいのは、マイナスでくくったときにかっこの中の符号を変え忘れることです。y² − 4y + 4 の前のマイナスは3つの項すべてにかかっています。「4項以上あるときは、3項をまとめて平方の形を作れないか」を探すのがコツです。' },
      { lv: 3, q: '(a + b)(b + c)(c + a) + abc を因数分解しよう。', a: '(a + b + c)(ab + bc + ca)', exp: 'この式は a、b、c のどの2つを入れかえても変わらない対称式です。a について整理すると、(a + b)(c + a) = a² + (b + c)a + bc なので、式は (b + c)a² + (b + c)²a + bc(b + c) + abc = (b + c)a² + {(b + c)² + bc}a + bc(b + c) です。これを a の2次式としてたすき掛けすると {(b + c)a + bc}{a + (b + c)} となり、(a + b + c)(ab + bc + ca) が得られます。a = b = c = 1 を代入すると、左辺 8 + 1 = 9、右辺 3 × 3 = 9 で確かめられます。' },
      { lv: 3, q: 'a³(b − c) + b³(c − a) + c³(a − b) を因数分解しよう。', a: '−(a − b)(b − c)(c − a)(a + b + c)', exp: 'a と b を入れかえると符号が逆になる交代式なので、(a − b)(b − c)(c − a) を因数にもちます。もとの式は4次式なので、残りは1次の対称式、つまり k(a + b + c) の形です。a³b の係数を比べます。もとの式では +1。(a − b)(b − c)(c − a)(a + b + c) を展開したときの a³b の係数は −1 なので、k = −1 です。答えを (a − b)(b − c)(a − c)(a + b + c) と書いても同じ式です(c − a を a − c にすると符号が変わるので、前のマイナスが消えます)。数値の代入(a = 0、b = 1、c = 2 で左辺 −6、右辺 −6)でも確かめましょう。' }
    ],
    faq: [
      ['なぜ「いちばん次数の低い文字」で整理するとよいの?', '次数が低い文字で整理すると、1次式や2次式として扱えるからです。1次式なら共通因数でくくるだけ、2次式ならたすき掛けで済みます。反対に、次数の高い文字で整理すると、3次式や4次式の因数分解が必要になり、手がかりが少なくなります。どの文字も同じ次数なら、どれか1つの文字(ふつうは a や x)について整理し、係数を因数分解します。'],
      ['因数分解は、どこまで分ければ「終わり」なの?', 'ふつうは【係数が有理数の範囲】で、これ以上分けられないところまでです。たとえば x² − 2 は有理数の範囲では因数分解できないので、そのままで終わりです。ただし「実数の範囲で」と指示があれば (x + √2)(x − √2) まで、「複素数の範囲で」なら x² + 1 = (x + i)(x − i) まで分けます。問題文に範囲の指定があるかどうかを必ず確かめましょう。']
    ]
  });

  add('m1_abs', {
    secs: [
      { h: 'さらに深く:絶対値の和の最小は「まん中の点」で決まる', t: '|x − a| は、数直線上の x と a の【距離】でした。この見方を使うと、絶対値がいくつも足された式の最小値が、計算しなくても分かります。\n例:f(x) = |x − 1| + |x − 4| + |x − 6| は、「x から 1、4、6 の3地点までの距離の合計」です。\nx を 4 の位置に置くと、1 と 6 の間にいるので、1 までと 6 までの距離の和は、いつも 6 − 1 = 5 で一定です。さらに 4 までの距離が 0 になるので、合計は 5 です。x を 4 から少しずらすと、1 と 6 までの和は 5 のままですが、4 までの距離が増えてしまいます。だから【最小値は x = 4 のとき 5】です。\nつまり、点が奇数個なら【まん中の点(中央値)】で最小になります。点が4個(1、2、3、7 など)のときは、まん中の2点(2 と 3)の間ならどこでも最小になります。これは、データの中央値が「各データからの距離の合計を最小にする値」であることと同じしくみです。\nただし、|x − 1| + 2|x + 2| のように係数がついていると、−2 の地点を「2人分」と数えることになります。点 1 に1人、点 −2 に2人いると考えると、3人のまん中は −2 です。実際に場合分けすると、x < −2 で −3x − 3、−2 ≦ x < 1 で x + 5、x ≧ 1 で 3x + 3 となり、x = −2 で最小値 3 をとります。\n場合分けをすると、グラフは【折れ線】になります。折れ曲がる点は、絶対値の中身が 0 になる x です。最小値は、傾きが負から正に変わる折れ曲がり点で起こります。', key: '絶対値の和は「距離の合計」。最小値は、点の中央値の位置でとる。係数は、その地点に人数が重なっていると考える。', ex: [{ q: 'f(x) = |x − 1| + 2|x + 2| の最小値と、そのときの x を求めよう。', hint: '中身が 0 になる x = −2、1 で場合を分ける。', steps: ['絶対値の中身が 0 になるのは x = 1 と x = −2 です。この2点を境に、x < −2、−2 ≦ x < 1、x ≧ 1 の3つに分けます。', 'x < −2 では、どちらの中身も負なので f(x) = −(x − 1) − 2(x + 2) = −3x − 3。傾き −3 で右下がりです。', '−2 ≦ x < 1 では、x + 2 ≧ 0、x − 1 < 0 なので f(x) = −(x − 1) + 2(x + 2) = x + 5。傾き 1 で右上がりです。', 'x ≧ 1 では f(x) = 3x + 3 で右上がりです。右下がりから右上がりに変わる x = −2 が最小で、f(−2) = 3 です。'], a: 'x = −2 のとき最小値 3', check: '「点 −2 に2人、点 1 に1人」と考えると、3人の中央値は −2 です。そこから点 1 までの距離 3 が最小値になり、場合分けの結果と一致します。' }] },
      { h: '実戦演習:文字をふくむ絶対値の不等式', t: '「不等式 |2x − 3| ≦ x + a が解をもつ条件」のように、右辺に文字がある問題では、|A| ≦ B ⇔ −B ≦ A ≦ B という書きかえが使えます(B が負なら左の式も成り立たないので、この書きかえはそのまま正しい)。\n戦略は、①2つの1次不等式に分けて x の範囲を求める、②2つの範囲が重なるかどうかで「解をもつ条件」を出す、の順です。\nグラフで考えると、V 字の折れ線 y = |2x − 3| と、傾き 1 の直線 y = x + a の位置関係の問題になります。V 字の谷の点 (3/2, 0) が直線の下(または上)にあれば、解があります。式と図の両方で確かめるのが、差がつくポイントです。', key: '|A| ≦ B は −B ≦ A ≦ B と書きかえてよい。解をもつ条件は「2つの範囲が重なる条件」になる。', ex: [{ q: '不等式 |2x − 3| ≦ x + a について、(1)a = 1 のときの解を求めよう。(2)解をもつような定数 a の値の範囲を求めよう。', hint: '−(x + a) ≦ 2x − 3 ≦ x + a と2つに分ける。', steps: ['|2x − 3| ≦ x + a は、−(x + a) ≦ 2x − 3 かつ 2x − 3 ≦ x + a と同じです。右辺が負のときは両方を満たす x がなくなるので、この書きかえで自動的に正しく処理されます。', '右側の不等式 2x − 3 ≦ x + a から x ≦ a + 3。左側の −x − a ≦ 2x − 3 から 3x ≧ 3 − a、つまり x ≧ (3 − a)/3 です。', '(1)a = 1 なら、2/3 ≦ x ≦ 4 です。', '(2)解をもつのは、(3 − a)/3 ≦ a + 3 となるときです。両辺に 3 をかけて 3 − a ≦ 3a + 9、つまり 4a ≧ −6 から a ≧ −3/2 です。'], a: '(1)2/3 ≦ x ≦ 4 (2)a ≧ −3/2', check: 'グラフで確かめます。V 字の谷の点は (3/2, 0) です。直線 y = x + a がこの点を通るのは a = −3/2 のときで、それより上なら V 字の上側に直線の一部が出るので解があります。a = −3/2 のときは x = 3/2 だけが解です。' }] }
    ],
    drill: [
      { lv: 2, q: '不等式 |x − 3| > 2x を解こう。', a: 'x < 1', exp: '中身 x − 3 の符号で場合を分けます。x ≧ 3 のとき、x − 3 > 2x から x < −3 ですが、x ≧ 3 と重ならないので解はありません。x < 3 のとき、−(x − 3) > 2x から 3 > 3x、つまり x < 1 で、これは x < 3 の範囲に入っています。2つの場合を合わせて x < 1 です。よくあるまちがいは、場合分けで出した答えを、その場合の範囲(x ≧ 3 など)と照らし合わせないことです。「求めた解が、その場合の条件を満たすか」を必ず確かめます。' },
      { lv: 3, q: '関数 f(x) = |x + 1| + |x − 2| + |x − 3| + |x − 7| の最小値と、最小値をとる x の範囲を求めよう。', a: '最小値 9(2 ≦ x ≦ 3 のとき)', exp: 'f(x) は、x から −1、2、3、7 の4地点までの距離の合計です。−1 と 7 の間にいれば、この2地点までの距離の和は 8 で一定。2 と 3 の間にいれば、この2地点までの距離の和は 1 で一定です。両方を同時に満たすのは 2 ≦ x ≦ 3 で、そのとき合計は 8 + 1 = 9 です。点が偶数個のときは、まん中の2点の間ならどこでも最小になり、最小値をとる x が1つに決まらないところに注意しましょう。f(2) = 3 + 0 + 1 + 5 = 9 で確かめられます。' },
      { lv: 3, q: 'x = 3 − √5 のとき、√(x² − 6x + 9) + √(x² + 2x + 1) の値を求めよう。', a: '4', exp: '√ の中はそれぞれ (x − 3)²、(x + 1)² なので、式は |x − 3| + |x + 1| です(√(A²) = |A|)。x − 3 = −√5 は負なので |x − 3| = √5。x + 1 = 4 − √5 は、√5 が約 2.24 なので正で、|x + 1| = 4 − √5。合計は √5 + 4 − √5 = 4 です。√(A²) = A としてしまうと、√(x² − 6x + 9) = x − 3 = −√5 という負の値になり、「√ は 0 以上」という約束に反します。中身の符号を、だいたいの値で必ず判断しましょう。' }
    ],
    faq: [
      ['負の数の「整数部分」はどう考えるの?', '整数部分は「その数をこえない最大の整数」なので、負の数では注意が必要です。たとえば −1.3 の整数部分は −1 ではなく −2 です(−1 は −1.3 より大きいので「こえない」に当てはまりません)。小数部分は −1.3 − (−2) = 0.7 となり、小数部分はいつも 0 以上 1 未満になります。「小数点より前の数字を取る」と覚えていると、負の数でまちがえます。'],
      ['不等式で、両辺を2乗してもいいの?', '両辺が【どちらも 0 以上】と分かっているときだけ、2乗しても大小は変わりません。0 ≦ A < B なら A² < B² です。しかし −3 < 2 を2乗すると 9 > 4 となり、向きが変わってしまいます。|x − 1| < |x + 3| のように両辺が絶対値なら、どちらも 0 以上なので2乗してよく、(x − 1)² < (x + 3)² から x > −1 と解けます。']
    ]
  });

  add('m1_set', {
    secs: [
      { h: 'さらに深く:「すべて」と「ある」は順番で意味が変わる', t: '命題の中に「すべての〜」と「ある〜」が両方出てくると、【並べる順番】で意味がまったく変わります。\n例1:「すべての実数 x に対して、ある実数 y があって、x + y = 0 となる」。これは真です。x がどんな数でも、y = −x を選べばよいからです。y は x に合わせて選び直してかまいません。\n例2:「ある実数 y があって、すべての実数 x に対して、x + y = 0 となる」。これは偽です。今度は y を先に1つ決めてしまい、その同じ y で、どの x に対しても x + y = 0 が成り立たなければなりません。x = −y 以外の x では成り立たないので偽です。\nつまり、【あとに出てくる文字は、前の文字に合わせて選べる】のです。例1では y が x のあとなので、x ごとに y を変えられます。例2では y が先なので、y は1つに固定されます。\n否定を作るときも、この順番が大切です。「すべて」と「ある」を入れかえ、最後の条件を否定します。例1の否定は「ある実数 x があって、すべての実数 y に対して x + y ≠ 0」です。順番はそのままで、それぞれの「すべて/ある」だけを入れかえます。\n入試では、「ある a について、すべての x で x² + ax + 1 > 0」のような形で出てきます。これは「うまい a が1つでも見つかればよい」という意味なので、a = 0 を選べば x² + 1 > 0 がすべての x で成り立ち、真です。一方「すべての a について」なら、a = 3 で x² + 3x + 1 の判別式が 5 > 0 となり、0 以下になる x があるので偽です。', key: '「すべて」と「ある」が並ぶ命題では、あとに出てくる文字は前の文字に合わせて選べる。順番を入れかえると別の命題になる。', ex: [{ q: '次の命題の真偽を答えよう。(1)すべての実数 x に対して、ある実数 y があって y² > x となる。(2)ある実数 y があって、すべての実数 x に対して y² > x となる。', hint: '(1)は x ごとに y を選べる。(2)は y を1つ決めてから、すべての x を調べる。', steps: ['(1)では、x が先に与えられ、それに合わせて y を選べます。x がどんな数でも、y = |x| + 1 とすれば y² = x² + 2|x| + 1 > |x| ≧ x となります。だから真です。', '(2)では、y を先に1つ決めます。y を決めると y² は1つの数です。', 'すると、x = y² + 1 のように、y² より大きい x がいくらでもとれます。その x では y² > x が成り立ちません。どんな y を選んでもこの反例が作れるので、(2)は偽です。', '同じ文字・同じ条件でも、「すべて」と「ある」の順番だけで真偽が変わったことに注目しましょう。'], a: '(1)真 (2)偽', check: '(2)の否定は「すべての実数 y に対して、ある実数 x があって y² ≦ x」です。x = y² とすれば成り立つので、否定が真、つまりもとの命題が偽であることが確かめられます。' }] },
      { h: '実戦演習:集合の要素の個数と、十分条件となる範囲', t: '集合の分野では、【要素の個数】を求める問題と、【条件を集合の包含に直す】問題がよく出ます。\n要素の個数では、和集合の個数 n(A∪B∪C) を求めるのに、【足しすぎた分を引き、引きすぎた分を足す】という考え方(包除原理)を使います。n(A∪B) = n(A) + n(B) − n(A∩B) を3つの集合に広げたものです。\n条件の問題では、「p が q であるための十分条件」を「P ⊂ Q」と言いかえ、数直線に2つの範囲をかきます。落とし穴は【端の等号】です。端が一致してよいのか、だめなのかを、白丸・黒丸で区別しながら判断します。', key: '個数は「足しすぎたら引く、引きすぎたら足す」。十分条件は包含に直し、端の点が入るかどうかを1つずつ確かめる。', ex: [{ q: '1 から 100 までの整数のうち、2、3、5 の少なくとも1つでわり切れるものは何個あるか。', hint: 'n(A∪B∪C) = n(A) + n(B) + n(C) − n(A∩B) − n(B∩C) − n(C∩A) + n(A∩B∩C)', steps: ['2、3、5 の倍数の集合をそれぞれ A、B、C とします。n(A) = 50、n(B) = 33、n(C) = 20 です(100 ÷ 3 = 33 余り 1 なので 33 個)。', '3つを足すと、2つの集合に入る数(たとえば 6 の倍数)を2回数えています。A∩B は 6 の倍数で 16 個、B∩C は 15 の倍数で 6 個、C∩A は 10 の倍数で 10 個。これを引きます。', 'すると、3つすべてに入る 30 の倍数は、3回足して3回引いたので、1回も数えられていません。30 の倍数は 3 個なので、これを足しもどします。', '50 + 33 + 20 − 16 − 6 − 10 + 3 = 74 です。'], a: '74 個', check: '余事象で確かめます。2、3、5 のどれでもわり切れない数は、1 から 30 までに 8 個(1, 7, 11, 13, 17, 19, 23, 29)あり、30 ごとに同じ並びがくり返されます。1〜90 に 24 個、91〜100 に 91、97 の 2 個で計 26 個。100 − 26 = 74 で一致します。' }, { q: '実数 x についての条件 p:x² − 3x + 2 ≦ 0、q:|x − a| < 1 がある。p が q であるための十分条件となるような定数 a の値の範囲を求めよう。', hint: 'p は 1 ≦ x ≦ 2、q は a − 1 < x < a + 1。P ⊂ Q となる条件を考える。', steps: ['p を解くと (x − 1)(x − 2) ≦ 0 から 1 ≦ x ≦ 2。q を解くと −1 < x − a < 1 から a − 1 < x < a + 1 です。', '「p が q の十分条件」は「p ⇒ q が真」、つまり集合で P ⊂ Q です。区間 [1, 2] が、区間 (a − 1, a + 1) の中にすっぽり入ればよいのです。', '左端について:1 が Q に入るには a − 1 < 1。ここで a − 1 = 1 だと、Q は端の 1 をふくまない(白丸)ので、P の 1 がはみ出します。だから等号はつきません。', '右端について:同じく 2 < a + 1 が必要です。2つを合わせて a < 2 かつ a > 1 です。'], a: '1 < a < 2', check: 'a = 1.5 なら Q は 0.5 < x < 2.5 で、[1, 2] をふくみます。a = 1 だと Q は 0 < x < 2 で、x = 2 が入らないので失敗します。端の値を代入して確かめると、等号の判断に自信がもてます。' }] }
    ],
    drill: [
      { lv: 2, q: '1 から 200 までの整数のうち、4 でも 6 でもわり切れないものは何個あるか。', a: '133 個', exp: '4 の倍数は 50 個、6 の倍数は 33 個です。4 でも 6 でもわり切れる数は、4 と 6 の最小公倍数 12 の倍数で、200 ÷ 12 = 16 余り 8 なので 16 個です。4 または 6 でわり切れる数は 50 + 33 − 16 = 67 個。どちらでもわり切れない数は、その余事象で 200 − 67 = 133 個です。よくあるまちがいは、「4 と 6 の両方でわり切れる数」を 4 × 6 = 24 の倍数と考えてしまうことです。両方の倍数は【最小公倍数】の倍数で、4 と 6 は 2 という公約数をもつので、24 ではなく 12 になります。' },
      { lv: 3, q: '実数 x についての条件 p:|x − 1| ≦ 2、q:x² − 2ax + a² − 9 ≦ 0 がある。p が q であるための十分条件となるような定数 a の値の範囲を求めよう。', a: '0 ≦ a ≦ 2', exp: 'p は −2 ≦ x − 1 ≦ 2 から −1 ≦ x ≦ 3。q は (x − a)² ≦ 9 から a − 3 ≦ x ≦ a + 3 です。p が q の十分条件 ⇔ P ⊂ Q ⇔ [−1, 3] が [a − 3, a + 3] にふくまれる、です。左端は a − 3 ≦ −1、右端は 3 ≦ a + 3 で、今度は Q も端をふくむ(黒丸)ので等号がつきます。a ≦ 2 かつ a ≧ 0 から 0 ≦ a ≦ 2。a = 0 のとき Q は [−3, 3] で、P の右端 3 と Q の右端が一致しますが、どちらも 3 をふくむので問題ありません。上の例題(白丸のとき)と、等号の扱いを比べておきましょう。' },
      { lv: 3, q: '命題「ある実数 a について、すべての実数 x で x² + ax + 1 > 0 が成り立つ」と、命題「すべての実数 a について、ある実数 x で x² + ax + 1 ≦ 0 となる」の真偽をそれぞれ答えよう。', a: '前者は真、後者は偽', exp: '後者は前者の否定になっています(「ある」と「すべて」を入れかえ、> 0 を ≦ 0 に変えた)。前者は、うまい a を1つ見つければ真です。a = 0 なら x² + 1 > 0 がすべての x で成り立つので真です。正確には、判別式 a² − 4 < 0、つまり −2 < a < 2 の a ならどれでもかまいません。前者が真なので、その否定である後者は偽です。後者を直接調べると、a = 0 のとき x² + 1 ≦ 0 となる x がないので、反例が見つかります。命題とその否定は、必ず一方だけが真になることも、確かめに使えます。' }
    ],
    faq: [
      ['「ある x について」は、「ただ1つの x について」という意味?', 'いいえ。数学の「ある」は【少なくとも1つ】という意味です。2つ以上あってもかまいません。「x² = 4 となる実数 x がある」は、x = 2 と x = −2 の2つがありますが、もちろん真です。「ただ1つ」と言いたいときは、「ただ1つ存在する」とはっきり書きます。日常語の「ある人が言った」は1人を思い浮かべますが、数学では人数を限定していないと考えましょう。'],
      ['空集合が、どんな集合の部分集合にもなるのはなぜ?', 'A ⊂ B は「A の要素はすべて B の要素」という意味でした。これが偽になるのは、「A の要素なのに B に入っていないもの」(反例)が1つでもあるときです。空集合 ∅ には要素が1つもないので、反例を作れません。だから、どんな B についても ∅ ⊂ B は真です。命題で言えば、仮定 p を満たすものが1つもないとき、「p ならば q」は真になる、ということと同じしくみです。']
    ]
  });
  add('m_h1', {
    secs: [
      { h: 'さらに深く:グラフから係数 a、b、c の符号を読む', t: '2次関数 y = ax² + bx + c のグラフが図で与えられ、「a、b、c、b² − 4ac、a + b + c の符号を答えよ」と聞かれることがあります。式を知らなくても、グラフの【どこを見ればどの値が分かるか】を知っていれば答えられます。\n【a】…グラフの向き。下に凸なら a > 0、上に凸なら a < 0。\n【c】…x = 0 を代入すると y = c なので、【y 軸との交点の y 座標】です。\n【b】…単独では見えませんが、軸の位置 x = −b/(2a) に出てきます。軸の位置と a の符号を組み合わせて判断します。たとえば a > 0 で軸が y 軸より右(−b/(2a) > 0)なら、b < 0 です。\n【b² − 4ac】…判別式です。x 軸と2点で交われば正、接すれば 0、離れていれば負です。\n【a + b + c】…x = 1 を代入した値 f(1) です。グラフの x = 1 の位置の高さを見ます。同じように a − b + c = f(−1)、4a + 2b + c = f(2) です。\nこのように、【係数の組み合わせを「ある x での値」と読みかえる】のがコツです。\n例:上に凸で、頂点が第1象限にあり、y 軸と負の部分で交わるグラフなら、a < 0、c < 0。軸は x > 0 なので −b/(2a) > 0 で、a < 0 だから b > 0。頂点が x 軸より上にあり上に凸なので、x 軸と2点で交わり b² − 4ac > 0 です。\nこの読み方は、文字をふくむ2次関数の「条件を図で考える」問題の土台になります。', key: 'a は向き、c は y 切片、b は軸の位置と a の組み合わせ、a + b + c は x = 1 での値。係数を「グラフのどこかの値」に読みかえる。', ex: [{ q: '2次関数 y = ax² + bx + c のグラフは下に凸で、x 軸と x = 1、x = 3 の2点で交わる。a、b、c、b² − 4ac、a + b + c、a − b + c の符号を答えよう。', hint: 'x 軸との交点が分かっているので、y = a(x − 1)(x − 3) と表せる。', steps: ['下に凸なので a > 0 です。x 軸と2点で交わるので b² − 4ac > 0 です。', '軸は2つの交点の真ん中で x = 2。−b/(2a) = 2 から b = −4a で、a > 0 なので b < 0 です。', 'c は y 切片です。y = a(x − 1)(x − 3) に x = 0 を代入すると y = 3a > 0 なので c > 0 です。', 'a + b + c = f(1) で、x = 1 は x 軸との交点なので 0。a − b + c = f(−1) で、x = −1 は2つの交点の外側なので、下に凸のグラフでは正です。'], a: 'a > 0、b < 0、c > 0、b² − 4ac > 0、a + b + c = 0、a − b + c > 0', check: '具体的に a = 1 とすると y = x² − 4x + 3。b = −4 < 0、c = 3 > 0、b² − 4ac = 4 > 0、a + b + c = 0、a − b + c = 8 > 0 で、すべて一致します。' }] },
      { h: '実戦演習:頂点が動くときの軌跡', t: '「t が変わるとき、放物線の頂点はどんな図形をえがくか」という問題では、頂点の座標を t で表し、そこから t を消します。\n戦略:①平方完成して頂点 (X, Y) を t の式で表す ②X の式を t について解き、Y の式に代入して t を消す ③t に範囲があれば、それを X の範囲に直す。\n落とし穴は③です。t の範囲を忘れると、軌跡全体(放物線全体)を答えてしまいます。たとえば t ≧ 0 という条件があれば、頂点の x 座標にも範囲がつき、軌跡は放物線の一部になります。', key: '頂点を (X, Y) とおいて t を消す。t の範囲は、X の範囲として必ず書き加える。', ex: [{ q: 't を 0 以上の実数とする。放物線 y = x² − 2(t + 1)x + 2t² の頂点がえがく図形を求めよう。', hint: '頂点の x 座標は t + 1。X = t + 1 から t = X − 1 として代入する。', steps: ['平方完成します。y = {x − (t + 1)}² − (t + 1)² + 2t² = {x − (t + 1)}² + t² − 2t − 1。', 'よって頂点は (t + 1, t² − 2t − 1)。これを (X, Y) とおくと、X = t + 1、Y = t² − 2t − 1 です。', 'X = t + 1 から t = X − 1。Y の式に代入すると、Y = (X − 1)² − 2(X − 1) − 1 = X² − 4X + 2 です。', 't ≧ 0 なので X = t + 1 ≧ 1。だから、頂点は放物線 y = x² − 4x + 2 の x ≧ 1 の部分をえがきます。'], a: '放物線 y = x² − 4x + 2 の x ≧ 1 の部分', check: 't = 0 のとき頂点は (1, −1)、t = 3 のとき (4, 2)。どちらも y = x² − 4x + 2 に代入すると成り立ちます(1 − 4 + 2 = −1、16 − 16 + 2 = 2)。' }] }
    ],
    drill: [
      { lv: 2, q: '放物線 y = x² + bx + c は点 (0, 3) を通り、頂点が直線 y = x + 1 の上にある。b、c の値を求めよう。', a: 'b = 4、c = 3 または b = −2、c = 3(y = x² + 4x + 3、y = x² − 2x + 3)', exp: '(0, 3) を通るので c = 3 です。平方完成すると y = (x + b/2)² + 3 − b²/4 なので、頂点は (−b/2, 3 − b²/4)。これが y = x + 1 の上にあるので、3 − b²/4 = −b/2 + 1。両辺を 4 倍して 12 − b² = −2b + 4、つまり b² − 2b − 8 = 0 で、(b − 4)(b + 2) = 0 から b = 4、−2 です。b = 4 のとき頂点 (−2, −1)、b = −2 のとき頂点 (1, 2) で、どちらも y = x + 1 の上にあります。2次方程式から2つの答えが出たら、両方を確かめて残すのが大切です。' },
      { lv: 3, q: '放物線 y = x² − 4x + 5 を、直線 y = 1 に関して対称移動した放物線の式を求めよう。', a: 'y = −x² + 4x − 3', exp: '移動後の点を (X, Y) とすると、直線 y = 1 について折り返す前の点は (X, 2 − Y) です(y 座標の平均が 1 になる点)。この点がもとの放物線の上にあるので、2 − Y = X² − 4X + 5。Y について解くと Y = −X² + 4X − 3 です。頂点で確かめると、もとの頂点 (2, 1) は直線 y = 1 の上にあるので動かず、移動後の頂点も (2, 1) で、向きだけが上に凸に変わります。x 軸に関する対称移動(y → −y)を「y = 0 について折り返す」と見れば、同じ考え方の特別な場合だと分かります。' },
      { lv: 3, q: '2次関数 y = ax² + bx + c のグラフは下に凸で、頂点が第4象限にあり、y 軸と正の部分で交わる。b、b² − 4ac、a − b + c の符号を答えよう。', a: 'b < 0、b² − 4ac > 0、a − b + c > 0', exp: '下に凸なので a > 0。頂点が第4象限にあるので、軸 x = −b/(2a) は正で、a > 0 から b < 0 です。頂点の y 座標が負で下に凸なので、グラフは x 軸と2点で交わり b² − 4ac > 0 です。a − b + c = f(−1) です。y 切片 c が正で、軸は正の側にあるので、x ≦ 0 の範囲ではグラフは右下がりで、x = −1 での値は x = 0 での値 c より大きく、正です。b の符号は「軸の位置」と「a の符号」の両方を使わないと決まらない点に注意しましょう。' }
    ],
    faq: [
      ['2次関数を決めるのに、なぜ条件が3つ必要なの?', 'y = ax² + bx + c には、決めるべき数が a、b、c の3つあるからです。1つの条件(たとえば「ある点を通る」)からは式が1つしか出ないので、3つの未知数を決めるには3つの条件が要ります。「頂点が (1, 2)」は x 座標と y 座標の2つの条件をふくむので、あと1つの点で決まります。条件の数を数えると、問題の条件に過不足がないかも確かめられます。'],
      ['x² の係数 a が同じ放物線は、すべて同じ形なの?', 'はい。a が同じなら、平方完成して y = a(x − p)² + q と書くと、y = ax² を平行移動しただけなので、ぴったり重なります(合同)。さらに、a がちがっても、すべての放物線は拡大・縮小すると重なる【相似】な図形です。y = 2x² を、原点を中心に 2 倍に拡大すると y = x² になります。円がすべて相似なのと同じように、放物線もすべて相似なのです。']
    ]
  });

  add('m_qmax', {
    secs: [
      { h: 'さらに深く:おきかえたら「新しい文字の範囲」を必ず調べる', t: '4次関数のような複雑な式でも、【同じかたまり】が出てくれば、そのかたまりを t とおいて2次関数にできます。\n例:y = (x² − 2x)² + 4(x² − 2x) + 1。t = x² − 2x とおくと、y = t² + 4t + 1 = (t + 2)² − 3 です。\nここで「t = −2 のとき最小値 −3」と答えると、まちがいです。理由は、t = x² − 2x = (x − 1)² − 1 なので、【t は −1 以上の値しかとれない】からです。t = −2 になる x は存在しません。\nそこで、t ≧ −1 という範囲(定義域)のもとで y = (t + 2)² − 3 の最小値を考えます。軸 t = −2 は範囲の外(左)にあるので、範囲の左端 t = −1 で最小になります。y = 1 − 4 + 1 = −2 で、t = −1 になるのは x = 1 のときです。\nこのように、おきかえは【見た目を2次関数にするだけでなく、定義域を作り直す作業】だと考えましょう。t の範囲は、t を x の関数と見て、その値域を求めればよいのです。\nこの考え方は、数学Ⅱの三角関数(t = sin θ なら −1 ≦ t ≦ 1)、指数関数(t = 2ˣ なら t > 0)、対数関数でも、まったく同じ形で出てきます。また、2変数の問題で y² = 1 − x² のように1文字を消すときも、「y² ≧ 0 だから −1 ≦ x ≦ 1」という隠れた範囲が生まれます。範囲を見落とすと答えが変わるので、入試でよく差がつきます。', key: 'おきかえた文字 t には、もとの x から決まる範囲がある。その範囲を定義域として最大・最小を考える。', ex: [{ q: '実数 x、y が x² + y² = 1 を満たすとき、x + y² の最大値と最小値を求めよう。', hint: 'y² = 1 − x² で y を消す。y² ≧ 0 から x の範囲が出る。', steps: ['y² = 1 − x² を代入すると、x + y² = x + 1 − x² = −x² + x + 1。x だけの2次関数になります。', 'ここで x の範囲を調べます。y² = 1 − x² ≧ 0 なので、x² ≦ 1、つまり −1 ≦ x ≦ 1 です。これが隠れた定義域です。', '平方完成すると −(x − 1/2)² + 5/4。軸 x = 1/2 は範囲の中なので、x = 1/2 で最大値 5/4。', '最小値は、軸から遠い方の端 x = −1 で、−1 − 1 + 1 = −1。x = 1 では 1 なので、こちらは最小ではありません。'], a: '最大値 5/4(x = 1/2、y = ±√3/2)、最小値 −1(x = −1、y = 0)', check: 'x の範囲を考えずに答えると、最小値は「ない」になってしまいます。x = 1/2 のとき y² = 3/4 で、1/2 + 3/4 = 5/4 となり、たしかに成り立ちます。' }] },
      { h: '実戦演習:2つの文字が自由に動くときの最小値', t: 'x と y が、どちらも自由に(条件なしに)動くときの最小値は、【1つの文字を固定して考える】のが基本戦略です。\nまず y を定数と思い、x の2次式として平方完成します。すると「x がどう動いても、これ以上小さくならない値」が y の式で出てきます。次に、その y の式を y について平方完成します。\nこれは結局、式を【(x と y の式)² + (y の式)² + 定数】の形に直すことと同じです。2乗はどれも 0 以上なので、両方の2乗を同時に 0 にできれば、そのとき最小になります。落とし穴は、2つの2乗が【同時に】0 になれるかを確かめ忘れることです。', key: '一方を固定して平方完成し、次にもう一方で平方完成する。最後に「2つの2乗が同時に 0 になる x、y」があるか確かめる。', ex: [{ q: 'x、y が実数のとき、x² − 2xy + 2y² − 2x + 4y + 3 の最小値と、そのときの x、y を求めよう。', hint: 'まず x の2次式と見て、x² − 2(y + 1)x の部分を平方完成する。', steps: ['x について整理すると x² − 2(y + 1)x + 2y² + 4y + 3。y を定数と見て平方完成します。', 'x² − 2(y + 1)x = {x − (y + 1)}² − (y + 1)² なので、式は {x − (y + 1)}² − (y + 1)² + 2y² + 4y + 3 = (x − y − 1)² + y² + 2y + 2。', '残りの y² + 2y + 2 を平方完成すると (y + 1)² + 1。全体は (x − y − 1)² + (y + 1)² + 1 です。', '2つの2乗が同時に 0 になるのは、y = −1 かつ x − y − 1 = 0、つまり x = 0 のときです。このとき最小値 1 です。'], a: 'x = 0、y = −1 のとき最小値 1', check: 'x = 0、y = −1 を代入すると 0 − 0 + 2 − 0 − 4 + 3 = 1 です。近くの値、たとえば x = 0.1、y = −1 では 1.01 となり、たしかに 1 より大きくなります。' }] }
    ],
    drill: [
      { lv: 2, q: '関数 y = (x² + 2x)² − 2(x² + 2x) − 3 の最小値と、そのときの x の値を求めよう。', a: '最小値 −4(x = −1 ± √2)', exp: 't = x² + 2x とおくと、t = (x + 1)² − 1 なので t ≧ −1 です。y = t² − 2t − 3 = (t − 1)² − 4。軸 t = 1 は範囲 t ≧ −1 の中にあるので、t = 1 で最小値 −4 です。t = 1 となる x は、x² + 2x = 1 を解いて x = −1 ± √2 です。今回は軸が t の範囲の中にあったので、範囲を考えなくても同じ答えになりますが、それは「たまたま」です。答えが同じでも、t ≧ −1 を書いて確かめる習慣をつけましょう。' },
      { lv: 3, q: '実数 x、y が x² + y² = 4 を満たすとき、2x + y² の最大値と最小値を求めよう。', a: '最大値 5(x = 1、y = ±√3)、最小値 −4(x = −2、y = 0)', exp: 'y² = 4 − x² を代入すると 2x + 4 − x² = −(x − 1)² + 5。y² ≧ 0 から 4 − x² ≧ 0 なので −2 ≦ x ≦ 2 です。軸 x = 1 は範囲の中なので、x = 1 で最大値 5。最小値は軸から遠い端 x = −2 で、−4 + 4 − 4 = −4 です。x の範囲を考えないと「最小値はない」とまちがえます。円の式から1文字を消すときは、消した文字の2乗が 0 以上であることから、残った文字に範囲がつくことを必ず確かめましょう。' },
      { lv: 3, q: 'x ≧ 0、y ≧ 0、x + y = 2 のとき、x³ + y³ の最大値と最小値を求めよう。', a: '最大値 8(x = 0, y = 2 または x = 2, y = 0)、最小値 2(x = y = 1)', exp: 'x³ + y³ = (x + y)³ − 3xy(x + y) = 8 − 6xy なので、xy の範囲が分かればよいのです。y = 2 − x を代入すると xy = x(2 − x) = −(x − 1)² + 1。y ≧ 0 から 0 ≦ x ≦ 2 で、この範囲で xy は最大 1(x = 1)、最小 0(x = 0, 2)です。xy が大きいほど x³ + y³ は小さくなるので、xy = 1 のとき最小値 2、xy = 0 のとき最大値 8 です。3次式でも、対称式を x + y と xy で表すと、2次関数の問題に直せます。' }
    ],
    faq: [
      ['おきかえで t の範囲を調べ忘れると、どんなまちがいになるの?', 't が実際にはとれない値で最大・最小を答えてしまいます。たとえば t = x² − 2x のとき、t は −1 以上です。y = (t + 2)² − 3 で「t = −2 のとき最小値 −3」と答えても、t = −2 となる x はないので、その値は実際には出てきません。軸が t の範囲の外にあるときに、このまちがいが起こります。t を決めたら、すぐに「t の範囲」を書く習慣をつけましょう。'],
      ['2変数の最小値で、なぜ「2乗の和」の形にすると分かるの?', '実数の2乗は必ず 0 以上なので、A² + B² + k は、A = 0 かつ B = 0 のとき最小値 k をとるからです。ただし、A と B を同時に 0 にできる x、y がないと、k は最小値になりません。x² + y² + (x + y − 2)² のように、3つの2乗を同時に 0 にできない場合は、別の方法で考える必要があります。最後に「そのときの x、y」を具体的に求めるのは、この確認のためです。']
    ]
  });

  add('m_disc', {
    secs: [
      { h: 'さらに深く:不等式の「解」から、もとの係数を決める', t: 'ふつうは「不等式を解く」問題ですが、入試では逆に、【解が分かっている不等式の係数を求める】問題がよく出ます。\n考え方の土台は、2次不等式の解とグラフの関係です。ax² + bx + c > 0 の解が −1 < x < 3 になるのは、放物線 y = ax² + bx + c が、x = −1 と x = 3 の【間だけ】で x 軸より上にあるときです。\n「間だけ上にある」のは、【上に凸】の放物線です。下に凸なら、上にあるのは外側になってしまいます。だから、まず【a < 0】が決まります。\nさらに、x 軸との交点が x = −1、3 なので、ax² + bx + c = a(x + 1)(x − 3) と表せます。あとは、分かっている係数と比べれば決まります。\n例:ax² + bx + 6 > 0 の解が −1 < x < 3 のとき、a(x + 1)(x − 3) = ax² − 2ax − 3a。定数項を比べて −3a = 6 から a = −2(たしかに負)。x の係数を比べて b = −2a = 4 です。\nこの考え方で大切なのは、【解の形(間か外側か)から a の符号が決まる】ことです。「x < α、β < x」が解なら下に凸で a > 0、「α < x < β」が解で不等号が > 0 なら a < 0 です。符号を確かめずに式だけ比べると、a の符号が条件と合わない答えを出してしまうことがあります。\nもう1つの応用が、「ax² + bx + c < 0 の解から、cx² + bx + a > 0 を解け」という、係数を並べかえた不等式です。a で係数を表してから、両辺を a でわります。a の符号によって不等号の向きが変わるので、ここでも符号が決め手になります。', key: '解の形(間か外側か)から、まず x² の係数の符号を決める。そのうえで a(x − α)(x − β) と係数を比べる。', ex: [{ q: 'x の2次不等式 ax² + bx + c < 0 の解が 1 < x < 2 であるとき、不等式 cx² + bx + a > 0 を解こう。', hint: '解が「間」で不等号が < 0 なので a > 0。b、c を a で表す。', steps: ['ax² + bx + c < 0 の解が 1 < x < 2(間)なので、グラフは下に凸で、a > 0 です。', 'x 軸との交点が 1、2 なので ax² + bx + c = a(x − 1)(x − 2) = ax² − 3ax + 2a。よって b = −3a、c = 2a です。', 'cx² + bx + a > 0 に代入すると 2ax² − 3ax + a > 0。a > 0 なので、両辺を a でわっても不等号の向きは変わらず、2x² − 3x + 1 > 0 です。', '(2x − 1)(x − 1) > 0 なので、x < 1/2、1 < x です。'], a: 'x < 1/2、1 < x', check: 'たとえば a = 1 とすると、もとの不等式は x² − 3x + 2 < 0(解 1 < x < 2 で条件どおり)、新しい不等式は 2x² − 3x + 1 > 0 です。x = 0 を入れると 1 > 0 で成り立ち、x = 0.7 では 0.98 − 2.1 + 1 = −0.12 で成り立ちません。答えの範囲と合っています。' }] },
      { h: '実戦演習:共通解と、整数解の個数', t: '2次方程式の応用で差がつくのが、【2つの方程式の共通解】と【不等式を満たす整数の個数】です。\n共通解の戦略は、共通解を x = α とおいて両方の式に代入し、【α² の項を引き算で消す】ことです。2次の項が消えると、α と定数 k だけの簡単な式になり、因数分解できることが多いです。ただし、「k = ○ のとき2つの式が同じになる」場合があるので、出てきた値をもとの式に戻して確かめます。\n整数解の個数の戦略は、解を数直線にかき、【端の数がどこまで動けるか】を調べることです。端が整数ちょうどのとき、その整数が入るか入らないかを、不等号(< か ≦ か)で判断します。', key: '共通解は x² の項を消すために引き算する。整数の個数は、端の点を数直線上で動かし、ちょうど整数になるときを確かめる。', ex: [{ q: '2つの2次方程式 x² + kx + 2 = 0、x² + 2x + k = 0 が共通の実数解をもつような定数 k の値と、そのときの共通解を求めよう。', hint: '共通解を α とおき、2式を引き算して α² を消す。', steps: ['共通解を α とおくと、α² + kα + 2 = 0 …① と α² + 2α + k = 0 …② が同時に成り立ちます。', '① − ② で α² が消えて、(k − 2)α + (2 − k) = 0、つまり (k − 2)(α − 1) = 0 です。よって k = 2 または α = 1。', 'k = 2 のとき、2つの式はどちらも x² + 2x + 2 = 0 になりますが、判別式が 4 − 8 < 0 で実数解がありません。これは条件に合いません。', 'α = 1 のとき、② に代入して 1 + 2 + k = 0 から k = −3。このとき①は x² − 3x + 2 = 0(解 1、2)、②は x² + 2x − 3 = 0(解 1、−3)で、共通解はたしかに 1 です。'], a: 'k = −3、共通解 x = 1', check: '「実数解」という条件がなければ、k = 2 のときも、2つの方程式は同じ式なので、2つの虚数解が共通解になります。問題文の「実数」という条件が、答えをしぼっていることに注意しましょう。' }, { q: '不等式 x² − (a + 1)x + a < 0 を満たす整数 x がちょうど2個となるような、定数 a の値の範囲を求めよう。', hint: '左辺は (x − 1)(x − a) と因数分解できる。a が 1 より大きいか小さいかで分ける。', steps: ['左辺を因数分解すると (x − 1)(x − a) < 0 です。解は 1 と a の「間」です。', 'a > 1 のとき、解は 1 < x < a。1 より大きい整数を小さい順に 2、3 の2個だけふくむには、3 < a であり、4 はふくまないので a ≦ 4 です(a = 4 なら x < 4 なので 4 は入りません)。', 'a < 1 のとき、解は a < x < 1。1 より小さい整数を大きい順に 0、−1 の2個だけふくむには、a < −1 であり、−2 はふくまないので a ≧ −2 です。', 'a = 1 のときは (x − 1)² < 0 となり解がないので、条件に合いません。'], a: '−2 ≦ a < −1、3 < a ≦ 4', check: 'a = 4 のとき解は 1 < x < 4 で整数は 2、3 の2個。a = 3 のときは 1 < x < 3 で整数は 2 だけ。端の値を代入すると、等号をつける側・つけない側が確かめられます。' }] }
    ],
    drill: [
      { lv: 2, q: '2次不等式 x² + ax + b < 0 の解が 2 < x < 5 となるような、定数 a、b の値を求めよう。', a: 'a = −7、b = 10', exp: 'x² の係数が 1(正)で、解が「間」の 2 < x < 5 なので、x² + ax + b = (x − 2)(x − 5) と表せます。右辺を展開すると x² − 7x + 10 なので、a = −7、b = 10 です。この問題では x² の係数が正と決まっているので、符号の矛盾は起こりません。もし「ax² + bx + 10 > 0 の解が 2 < x < 5」なら、上に凸で a < 0 となり、a(x − 2)(x − 5) の定数項 10a = 10 から a = 1 となって a < 0 と矛盾します。このように、条件によっては「そのような a はない」となることもあります。' },
      { lv: 3, q: '2つの2次方程式 x² − 2x + k = 0、x² + kx − 2 = 0 が、少なくとも1つの共通な実数解をもつような定数 k の値を求めよう。', a: 'k = 1(共通解 x = 1)、k = −2(共通解 x = 1 ± √3)', exp: '共通解を α として2式を引き算すると (−2 − k)α + (k + 2) = 0、つまり (k + 2)(1 − α) = 0。よって k = −2 または α = 1 です。α = 1 のとき、1 − 2 + k = 0 から k = 1。このとき1つ目は (x − 1)² = 0、2つ目は x² + x − 2 = 0(解 1、−2)で、共通解 1 をもちます。k = −2 のとき、2つの式はどちらも x² − 2x − 2 = 0 となり、実数解 1 ± √3 をもつので、2つとも共通解です。k = −2 の場合を「意味がない」と捨てると答えが足りなくなります。2式が一致する場合は、実数解があるかを判別式で確かめて判断します。' },
      { lv: 3, q: '2次不等式 ax² + bx + 6 > 0 の解が −1 < x < 3 であるとき、定数 a、b の値を求め、さらに不等式 bx² + 6x + a ≦ 0 を解こう。', a: 'a = −2、b = 4。bx² + 6x + a ≦ 0 の解は −(3 + √17)/4 ≦ x ≦ (−3 + √17)/4', exp: '解が「間」で不等号が > 0 なので、上に凸で a < 0 です。ax² + bx + 6 = a(x + 1)(x − 3) = ax² − 2ax − 3a と比べ、−3a = 6 から a = −2(負で条件に合う)、b = −2a = 4 です。次の不等式は 4x² + 6x − 2 ≦ 0、両辺を 2 でわって 2x² + 3x − 1 ≦ 0。2x² + 3x − 1 = 0 を解の公式で解くと x = (−3 ± √17)/4 なので、その間が答えです。約 −1.78 ≦ x ≦ 0.28 で、x = 0 を代入すると −1 ≦ 0 で成り立つことも確かめられます。' }
    ],
    faq: [
      ['不等式の解から係数を求めるとき、なぜ x² の係数の符号を先に決めるの?', '同じ2つの交点をもつ放物線でも、下に凸か上に凸かで、不等式の解が「間」になるか「外側」になるかが逆になるからです。解の形を見れば、向き、つまり x² の係数の符号が決まります。符号を確かめずに係数を比べると、条件と合わない(符号が逆の)答えを出してしまうことがあります。また、あとで両辺を x² の係数でわるときに、不等号の向きを決めるのにも使います。'],
      ['共通解の問題で、引き算をするのはなぜ?', '2つの式の x² の係数がそろっているとき、引き算をすると【2次の項が消えて1次式になる】からです。2次方程式を2つ同時に解くより、1次式の方がずっと簡単です。x² の係数がそろっていなければ、片方を何倍かしてそろえてから引きます。また、定数項をそろえて引き、x² と x だけの式にする方法が便利なこともあります。どの項を消すと楽になるかを見て選びましょう。']
    ]
  });

  add('m_h2', {
    secs: [
      { h: 'さらに深く:15°や22.5°の三角比は「二等辺三角形」で作れる', t: '三角比の値は、30°・45°・60°以外は覚えていない人が多いでしょう。ところが、15°や22.5°の三角比は、図形の工夫だけで正確に求められます。カギは、【二等辺三角形の外角は、底角の2倍】という性質です。\n22.5°の作り方:直角二等辺三角形 ABC(∠C = 90°、AC = BC = 1、AB = √2)を考えます。辺 CA を A の外側にのばし、AD = AB = √2 となる点 D をとります。三角形 ABD は AB = AD の二等辺三角形なので、底角 ∠ADB と ∠ABD は等しく、その和が外角 ∠BAC = 45° に等しくなります。だから ∠ADB = 22.5° です。\n直角三角形 DBC で見ると、DC = 1 + √2、BC = 1 なので、tan 22.5° = 1/(1 + √2) = √2 − 1 です(分母を有理化しました)。\n15°の作り方も同じです。∠C = 90°、∠A = 30° の直角三角形(BC = 1、AC = √3、AB = 2)で、CA を A の外側にのばして AD = AB = 2 とします。すると ∠ADB = 30° ÷ 2 = 15° で、tan 15° = 1/(2 + √3) = 2 − √3 です。さらに DB² = (2 + √3)² + 1 = 8 + 4√3 から DB = √6 + √2(実際に (√6 + √2)² = 8 + 4√3)と分かり、sin 15° = 1/(√6 + √2) = (√6 − √2)/4 も出ます。\nこれは数学Ⅱの「加法定理」や「半角の公式」で出す値と、まったく同じ値になります。公式は、こうした図形の工夫を、どんな角でも使えるように一般化したものなのです。', key: '二等辺三角形の外角は底角の2倍。この性質を使えば、知っている角の「半分」の三角比が図形だけで求められる。', ex: [{ q: '∠C = 90°、∠A = 30°、BC = 1 の直角三角形 ABC で、辺 CA を A の側にのばし、AD = AB となる点 D をとる。∠ADB の大きさと tan∠ADB、cos∠ADB を求めよう。', hint: '三角形 ABD は二等辺三角形。外角 ∠BAC = 30°。', steps: ['30°・60°の直角三角形の辺の比 1 : √3 : 2 から、BC = 1、AC = √3、AB = 2 です。だから AD = 2 です。', '三角形 ABD は AB = AD の二等辺三角形なので ∠ADB = ∠ABD。この2つの和は、外角 ∠BAC = 30° に等しいので、∠ADB = 15° です。', '直角三角形 DBC で、DC = DA + AC = 2 + √3、BC = 1 なので、tan 15° = BC/DC = 1/(2 + √3)。分母を有理化すると 2 − √3 です。', '斜辺 DB は三平方の定理で DB² = (2 + √3)² + 1² = 8 + 4√3。(√6 + √2)² = 8 + 2√12 = 8 + 4√3 なので DB = √6 + √2。cos 15° = DC/DB = (2 + √3)/(√6 + √2) を有理化して (√6 + √2)/4 です。'], a: '∠ADB = 15°、tan 15° = 2 − √3、cos 15° = (√6 + √2)/4', check: '2 − √3 ≒ 0.268、(√6 + √2)/4 ≒ 0.966 で、関数電卓の tan 15° ≒ 0.2679、cos 15° ≒ 0.9659 と一致します。sin²15° + cos²15° = (8 − 4√3)/16 + (8 + 4√3)/16 = 1 でも確かめられます。' }] },
      { h: '実戦演習:2地点からの仰角で高さを求める', t: '測量の問題は、図に【直角三角形】と【二等辺三角形】を見つけられるかで、計算の量が大きく変わります。\n2地点から仰角を測る問題では、ふつうは「高さを h とおき、2つの直角三角形で水平距離を h で表して、差が地点間の距離になる」という方程式を立てます。これは確実な方法です。\nしかし、仰角が 15° と 30° のように【ちょうど2倍】になっているときは、頂上・2地点がつくる三角形が二等辺三角形になり、方程式なしで一気に解けます。外角の性質を使う、上の「さらに深く」と同じしくみです。\n落とし穴は、仰角を「地点から見上げた角」ではなく、頂上の角とまちがえることと、目の高さの扱いを忘れることです。', key: '2つの仰角が2倍の関係なら、二等辺三角形ができる。図の中の外角に注目すると、計算が大きく減る。', ex: [{ q: '平地に立つ塔の頂上 P を、地点 A から見上げると仰角は 15° だった。塔に向かってまっすぐ 100 m 進んだ地点 B から見上げると、仰角は 30° だった。塔の高さを求めよう(目の高さは考えない)。', hint: '三角形 ABP で、外角 ∠PBH = 30° と ∠PAB = 15° に注目する(H は塔の根元)。', steps: ['塔の根元を H とします。A、B、H は一直線で、B は A と H の間にあります。三角形 ABP の外角 ∠PBH は 30° です。', '外角は、となりにない2つの内角の和なので、∠PBH = ∠PAB + ∠APB。30° = 15° + ∠APB から ∠APB = 15° です。', 'すると三角形 ABP は ∠PAB = ∠APB = 15° の二等辺三角形で、BP = AB = 100 m です。', '直角三角形 PBH で、PH = BP × sin 30° = 100 × 1/2 = 50 m です。'], a: '50 m', check: '別解:高さを h とすると、AH = h/tan 15° = h/(2 − √3) = (2 + √3)h、BH = h/tan 30° = √3 h。差が 100 なので (2 + √3)h − √3 h = 2h = 100、h = 50 で一致します。' }] }
    ],
    drill: [
      { lv: 2, q: '直線 y = −√3 x + 1 と、x 軸の正の向きとのなす角 θ(0° ≦ θ < 180°)を求めよう。', a: 'θ = 120°', exp: '直線の傾きは、x 軸の正の向きとなす角 θ を使って tan θ と表せます。単位円で、角 θ の点 P(cos θ, sin θ) と原点を結ぶ直線の傾きが sin θ/cos θ = tan θ だからです。傾きが −√3 なので tan θ = −√3。0° ≦ θ < 180° でこれを満たすのは θ = 120° です。傾きが負のとき θ は鈍角になります。y 切片の 1 は、角度には関係しません(平行移動しても角度は変わらないため)。' },
      { lv: 3, q: 'tan 75° の値を求めよう。また、0° < θ < 90° で tan θ = 2 + √3 となる θ を答えよう。', a: 'tan 75° = 2 + √3、θ = 75°', exp: '直角三角形の2つの鋭角は θ と 90° − θ で、片方の「むかい」はもう片方の「となり」です。だから tan(90° − θ) = 1/tan θ が成り立ちます。tan 15° = 2 − √3 なので、tan 75° = 1/(2 − √3) = (2 + √3)/((2 − √3)(2 + √3)) = 2 + √3 です。0° < θ < 90° では tan θ は θ とともに増えるので、tan θ = 2 + √3 となる θ はただ1つで、75° です。(2 − √3)(2 + √3) = 1 なので、2 − √3 と 2 + √3 はたがいに逆数の関係にある、と覚えておくと便利です。' },
      { lv: 3, q: '0° < θ < 90° で、tan θ + 1/tan θ = 4 のとき、sin θ cos θ と sin θ + cos θ の値を求めよう。', a: 'sin θ cos θ = 1/4、sin θ + cos θ = √6/2', exp: 'tan θ = sin θ/cos θ を代入すると、sin θ/cos θ + cos θ/sin θ = (sin²θ + cos²θ)/(sin θ cos θ) = 1/(sin θ cos θ)。これが 4 なので sin θ cos θ = 1/4 です。次に (sin θ + cos θ)² = 1 + 2 sin θ cos θ = 3/2。θ が鋭角なので sin θ + cos θ > 0 で、√(3/2) = √6/2 です。実はこのときの θ は 15° または 75° で、sin 15° cos 15° = (√6 − √2)(√6 + √2)/16 = 4/16 = 1/4 となり、たしかに成り立ちます。2乗して求めたあとは、符号を θ の範囲で決めるのを忘れないようにしましょう。' }
    ],
    faq: [
      ['三角比の表の値(sin 1° など)は、どうやって作ったの?', '昔の人は、図形の工夫で 15°、18°(正五角形を使う)などの値を求め、そこから半分の角や、和・差の角の値を公式でつないで表を作りました。現在は、数学Ⅲ以降で学ぶ「無限に続く足し算(級数)」を使って、コンピュータが好きな精度で計算しています。表の値は小数第4位などで打ち切った近い値なので、問題で「表を使え」とあるときは、答えも近い値になります。'],
      ['三角比で、なぜ θ の範囲を 0° 〜 180° にするの?', '数学Ⅰの三角比は、主に三角形の辺や角を計算するために使うからです。三角形の1つの角は 0° より大きく 180° より小さいので、この範囲で十分なのです。単位円で定義を広げたおかげで、鈍角の三角形にも正弦定理・余弦定理が使えるようになりました。数学Ⅱでは、回転や波を表すために、さらに 360° をこえる角や負の角(一般角)まで広げます。']
    ]
  });
  add('m_sincos', {
    secs: [
      { h: 'さらに深く:三角形の形を決める(辺だけ・角だけの式にそろえる)', t: '「a cos B = b cos A を満たす三角形はどんな形か」のように、辺と角が混ざった等式から三角形の形を決める問題があります。このとき大切なのは、【式を辺だけ、または角だけにそろえる】ことです。混ざったままでは比べられません。\n辺だけにそろえる道具が、余弦定理 cos A = (b² + c² − a²)/(2bc) と、正弦定理 sin A = a/(2R) です。これで cos や sin を辺の式に置きかえられます。\n例:a cos B = b cos A。cos B = (c² + a² − b²)/(2ca)、cos A = (b² + c² − a²)/(2bc) を代入すると、\na × (c² + a² − b²)/(2ca) = b × (b² + c² − a²)/(2bc)\n両辺とも分母が 2c になるので、c² + a² − b² = b² + c² − a²、つまり 2a² = 2b² で、a = b(長さは正)。【CA = CB の二等辺三角形】です。\n図で見ると、a cos B は「辺 AB の上に、C から下ろした垂線の足 H までの長さ BH」、b cos A は「AH」です(鋭角のとき)。BH = AH なら、垂線の足が AB の真ん中にあるので二等辺三角形になる、と納得できます。\n注意したいのは、【両辺を同じ式でわるとき】です。たとえば a² − b² = 0 または c² = a² + b² のように、「積 = 0」の形になる式で、片方の因数でわってしまうと、もう1つの場合(直角三角形)を落とします。わる代わりに因数分解して、「〜または〜」として両方を残しましょう。答えの書き方も、「a = b の二等辺三角形、または C = 90° の直角三角形」のように、どの辺が等しいか・どの角が直角かまで書きます。', key: '辺と角が混ざった式は、正弦定理・余弦定理で辺だけの式にする。わり算はせず因数分解し、「または」の場合を落とさない。', ex: [{ q: '三角形 ABC で、a cos A = b cos B が成り立つとき、この三角形はどんな形か。', hint: '余弦定理で cos A、cos B を辺で表し、分母をはらって因数分解する。', steps: ['cos A = (b² + c² − a²)/(2bc)、cos B = (c² + a² − b²)/(2ca) を代入します。', 'a(b² + c² − a²)/(2bc) = b(c² + a² − b²)/(2ca)。両辺に 2abc をかけると a²(b² + c² − a²) = b²(c² + a² − b²) です。', '展開して整理すると a²c² − a⁴ = b²c² − b⁴、つまり c²(a² − b²) − (a⁴ − b⁴) = 0。a⁴ − b⁴ = (a² − b²)(a² + b²) なので、(a² − b²)(c² − a² − b²) = 0 です。', 'よって a² = b²(a = b)または c² = a² + b²(C = 90°)。a² − b² でわってしまうと、直角三角形の場合を落とすところでした。'], a: 'a = b の二等辺三角形、または C = 90° の直角三角形', check: '3辺 3、4、5(C = 90°)で確かめると、cos A = 4/5、cos B = 3/5 で、a cos A = 3 × 4/5 = 12/5、b cos B = 4 × 3/5 = 12/5 となり、たしかに成り立ちます。' }] },
      { h: '実戦演習:空間図形の計量(三角すいの体積)', t: '空間図形の問題では、【平面の三角形を取り出して、正弦定理・余弦定理を使う】のが基本です。\n三角すい OABC で OA = OB = OC のとき、頂点 O から底面 ABC に下ろした垂線の足 H は、底面の三角形の【外心】になります。なぜなら、直角三角形 OAH、OBH、OCH は斜辺 OA = OB = OC と OH が共通なので合同になり、HA = HB = HC となるからです。\n戦略:①底面の三角形を余弦定理・正弦定理で調べ、面積と外接円の半径 R を出す ②三平方の定理で高さ OH = √(OA² − R²) を出す ③体積 = (1/3) × 底面積 × 高さ。\n落とし穴は、外心と重心をまちがえることです。等しいのは「頂点までの距離」なので、外心です。', key: '頂点から3つの頂点までの距離が等しい三角すいでは、垂線の足は底面の外心。高さは √(辺² − R²) で出る。', ex: [{ q: '三角すい OABC で、AB = 5、BC = 7、CA = 8、OA = OB = OC = 7 である。この三角すいの体積を求めよう。', hint: '底面の角 A(辺 BC = 7 のむかい)を余弦定理で求める。', steps: ['底面の三角形 ABC で、BC = 7 のむかいの角 A について、cos A = (5² + 8² − 7²)/(2 × 5 × 8) = 40/80 = 1/2 なので A = 60° です。', '底面積は (1/2) × 5 × 8 × sin 60° = 10√3。外接円の半径は正弦定理で 2R = 7/sin 60° から R = 7/√3 です。', 'O から底面に下ろした垂線の足 H は、OA = OB = OC なので外心です。直角三角形 OAH で、OH² = OA² − R² = 49 − 49/3 = 98/3、OH = 7√6/3 です。', '体積 = (1/3) × 10√3 × 7√6/3 = 70√18/9 = 70 × 3√2/9 = 70√2/3 です。'], a: '70√2/3', check: '小数で確かめると、底面積 ≒ 17.32、高さ ≒ 5.72 で、(1/3) × 17.32 × 5.72 ≒ 33.0。70√2/3 ≒ 33.0 と一致します。' }] }
    ],
    drill: [
      { lv: 2, q: '3辺の長さが 5、6、7 の三角形の面積を求めよう。', a: '6√6', exp: 'まず1つの角の cos を余弦定理で求めます。長さ 7 の辺のむかいの角を θ とすると、cos θ = (25 + 36 − 49)/(2 × 5 × 6) = 12/60 = 1/5。sin θ = √(1 − 1/25) = √24/5 = 2√6/5(三角形の角なので sin θ > 0)。面積は (1/2) × 5 × 6 × 2√6/5 = 6√6 です。別解として、3辺から直接面積を出す【ヘロンの公式】S = √(s(s − a)(s − b)(s − c))(s は3辺の和の半分)を使うと、s = 9 で S = √(9 × 4 × 3 × 2) = √216 = 6√6 となり一致します。' },
      { lv: 3, q: '三角形 ABC で sin A = 2 cos B sin C が成り立つとき、この三角形はどんな形か。理由もつけて答えよう。', a: 'b = c の二等辺三角形(AB = AC)', exp: 'sin と cos が混ざっているので、どちらも辺に直します。外接円の半径を R とすると、正弦定理から sin A = a/(2R)、sin C = c/(2R)。余弦定理から cos B = (c² + a² − b²)/(2ca)。代入すると a/(2R) = 2 × (c² + a² − b²)/(2ca) × c/(2R)。両辺に 2R をかけて整理すると a = (c² + a² − b²)/a、つまり a² = c² + a² − b² で、b² = c²。b > 0、c > 0 なので b = c です。B = C の二等辺三角形なら A = 180° − 2B で、sin A = sin 2B となることも確かめになります(数学Ⅱの2倍角の公式 sin 2B = 2 sin B cos B)。' },
      { lv: 3, q: '1辺の長さが 6 の正四面体 ABCD で、辺 AB の中点を M とする。cos∠CMD の値と、正四面体の体積を求めよう。', a: 'cos∠CMD = 1/3、体積 18√2', exp: 'CM と DM は正三角形の高さなので 6 × √3/2 = 3√3、CD = 6 です。三角形 CMD で余弦定理を使うと cos∠CMD = (27 + 27 − 36)/(2 × 3√3 × 3√3) = 18/54 = 1/3。体積は、三角形 CMD を底面と見て、AB がこの面に垂直(AB ⊥ CM、AB ⊥ DM)であることを使います。三角形 CMD の面積は (1/2) × 3√3 × 3√3 × sin∠CMD で、sin∠CMD = √(1 − 1/9) = 2√2/3 なので 9√2。正四面体は、この面で高さ AM = 3 と BM = 3 の2つの三角すいに分かれるので、体積は (1/3) × 9√2 × 6 = 18√2 です。' }
    ],
    faq: [
      ['ヘロンの公式は、覚えたほうがいいの?', '覚えておくと、3辺が整数のときの面積の検算に便利です。ただし、辺に √ が入ると計算がかえって大変になります。教科書の基本は「余弦定理で cos → sin² + cos² = 1 で sin → (1/2)bc sin A」で、これはどんな三角形にも使えます。入試ではこの流れで解き、ヘロンの公式は答えの確かめに使う、というのがおすすめです。'],
      ['三角形の形を決める問題で、辺の式にするか角の式にするか、どう選ぶの?', '式に cos が入っていれば余弦定理で辺に、sin だけなら正弦定理(sin A = a/(2R))で辺にするのが、ほぼいつでも使える方法です。辺だけの式は、展開・因数分解という慣れた計算で処理できるからです。一方、sin 2A = sin 2B のように角の関係が見やすい式は、角のまま考える方が早いこともあります。迷ったら、まず辺の式に直しましょう。']
    ]
  });

  add('m1_data', {
    secs: [
      { h: 'さらに深く:共分散の符号は「4つの区画」で決まる', t: '相関係数 r は、共分散 sxy を、2つの標準偏差の積 sx × sy でわったものでした。分母の標準偏差はいつも正なので、【r の符号は共分散の符号で決まります】。では、共分散の符号は何で決まるのでしょうか。\n共分散は、「x の偏差 × y の偏差」の平均です。散布図に、平均値の位置で縦線(x = x̄)と横線(y = ȳ)を引くと、図は4つの区画に分かれます。\n・右上の区画:x も y も平均より大きいので、偏差の積は(正)×(正)= 正。\n・左下の区画:(負)×(負)= 正。\n・左上と右下の区画:偏差の積は負。\nだから、【右上・左下に点が多ければ共分散は正(正の相関)、左上・右下に多ければ負(負の相関)】になります。さらに、平均から遠い点ほど積の絶対値が大きく、共分散への影響が大きくなります。\n例:5人のデータ (x, y) = (1, 3)、(2, 2)、(3, 5)、(4, 6)、(5, 4)。平均は x̄ = 3、ȳ = 4。偏差の組は (−2, −1)、(−1, −2)、(0, 1)、(1, 2)、(2, 0) で、積は 2、2、0、2、0。合計 6 を 5 でわって共分散は 1.2 です。x と y の分散はどちらも 2 なので、r = 1.2/(√2 × √2) = 0.6 です。\nなお、共分散そのものは単位(点 × cm など)に左右されるので、大きさだけでは相関の強さを比べられません。標準偏差でわって単位を消したものが相関係数で、これは必ず −1 以上 1 以下になります。r = ±1 となるのは、すべての点が1本の直線(傾きが正か負)の上に並ぶときだけです。', key: '共分散は「偏差の積の平均」。平均の線で4つに分けた区画のうち、右上・左下に点が多いと正、左上・右下に多いと負になる。', ex: [{ q: '4人のデータ (x, y) = (2, 1)、(4, 5)、(6, 3)、(8, 7) について、共分散と相関係数を求めよう。', hint: '先に平均を求め、偏差の表を作る。', steps: ['x の平均は (2 + 4 + 6 + 8)/4 = 5、y の平均は (1 + 5 + 3 + 7)/4 = 4 です。', '偏差は x が −3、−1、1、3、y が −3、1、−1、3。偏差の積は 9、−1、−1、9 で、合計 16。共分散は 16/4 = 4 です。', '分散は、x が (9 + 1 + 1 + 9)/4 = 5、y も (9 + 1 + 1 + 9)/4 = 5。標準偏差はどちらも √5 です。', '相関係数は r = 4/(√5 × √5) = 4/5 = 0.8 です。'], a: '共分散 4、相関係数 0.8', check: '偏差の積を見ると、右上と左下の区画の点(積 9 の2人)が大きく、左上・右下の点(積 −1 の2人)は小さいので、正の相関になることが計算前に予想できます。' }] },
      { h: '実戦演習:データの一部をまちがえていたとき', t: '「1人の得点を記録しまちがえていた。正しい平均値と分散を求めよ」という問題は、データ全体が分からなくても解けます。\n戦略は、平均値と分散を、【データの合計】と【データの2乗の合計】に直すことです。\n・合計 = 平均値 × 人数\n・2乗の合計 = (分散 + 平均値²) × 人数(分散 = 2乗の平均 − 平均の2乗 から)\nまちがえた値を引き、正しい値を足せば、新しい合計と2乗の合計が出ます。そこからもう一度、平均値と分散を計算します。\n落とし穴は、「1人の値が 20 点増えたから、分散も何かを足せばよい」と考えることです。分散は平均値とのずれで決まるので、平均値が変わると全員の偏差が変わります。必ず2乗の合計を経由しましょう。', key: '平均値と分散は「合計」と「2乗の合計」に直してから修正する。分散を直接いじらない。', ex: [{ q: '10人のテストの得点の平均値は 60 点、分散は 40 だった。ところが、1人の得点を 50 点と記録していたが、正しくは 70 点だった。正しい平均値と分散を求めよう。', hint: '合計と2乗の合計を求め、50 を 70 に入れかえる。', steps: ['合計は 60 × 10 = 600 点です。2乗の平均は 分散 + 平均値² = 40 + 3600 = 3640 なので、2乗の合計は 36400 です。', '50 を 70 に直すと、合計は 600 − 50 + 70 = 620、2乗の合計は 36400 − 2500 + 4900 = 38800 です。', '正しい平均値は 620/10 = 62 点です。', '正しい2乗の平均は 3880 なので、正しい分散は 3880 − 62² = 3880 − 3844 = 36 です。'], a: '平均値 62 点、分散 36', check: '分散が小さくなったのは、50 点(平均より 10 点低い)を、新しい平均 62 点に近い 70 点(8 点高い)に直したので、全体のばらつきが減ったからです。直感とも合っています。' }] }
    ],
    drill: [
      { lv: 2, q: '5人のデータの平均値が 6、分散が 4 である。ここに得点 6 の人が1人加わったとき、6人の平均値と分散を求めよう。', a: '平均値 6、分散 10/3', exp: '加わった人の得点 6 は平均値と同じなので、合計は 30 + 6 = 36 で、平均値は 36/6 = 6 のままです。分散は「偏差の2乗の平均」です。5人の偏差の2乗の合計は 4 × 5 = 20、加わった人の偏差は 0 なので、合計は 20 のまま。人数が 6 人になるので、分散は 20/6 = 10/3 です。平均値と同じ値を加えても、平均値は変わりませんが、分散は【小さくなる】ことに注意しましょう。ばらつきのない人が1人増えたことで、1人あたりのずれが薄まったのです。' },
      { lv: 3, q: '変量 x の平均値を m、標準偏差を s(s > 0)とする。z = 50 + 10(x − m)/s と変換したとき、z の平均値と標準偏差を求めよう。', a: '平均値 50、標準偏差 10', exp: 'z = (10/s)x + (50 − 10m/s) という1次式の変換です。y = ax + b のとき、平均値は a × (x の平均値) + b、標準偏差は |a| × (x の標準偏差) でした。平均値は (10/s) × m + 50 − 10m/s = 50。標準偏差は (10/s) × s = 10 です。これが【偏差値】のしくみで、どんなテストでも、平均点の人がちょうど 50、平均より標準偏差1つ分高い人が 60 になるように変換しています。だから、平均点や散らばりがちがうテストの成績も、偏差値なら比べやすくなるのです。' },
      { lv: 3, q: 'ある変量 x、y について、x の分散が 9、y の分散が 16、x + y の分散が 37 だった。x と y の共分散と相関係数を求めよう。', a: '共分散 6、相関係数 0.5', exp: 'x + y の偏差は「x の偏差 + y の偏差」なので、その2乗の平均を展開すると、(x + y の分散) = (x の分散) + 2 × (共分散) + (y の分散) となります。37 = 9 + 2 × 共分散 + 16 から、共分散は 6 です。相関係数は 6/(3 × 4) = 0.5 です。この式から、x と y に正の相関があると、合計 x + y の散らばりは、それぞれの分散の和より大きくなることが分かります。反対に負の相関なら、たがいに打ち消し合って合計の散らばりは小さくなります。' }
    ],
    faq: [
      ['散布図の点がすべて一直線上にあれば、相関係数は必ず 1 か −1 なの?', '直線の傾きが正なら 1、負なら −1 です。ただし、直線が水平(y がすべて同じ値)や垂直のときは例外です。たとえば y がすべて同じ値なら、y の標準偏差が 0 になり、相関係数の分母が 0 になるので、相関係数は【定義できません】。「一直線 ⇒ ±1」は、傾きが 0 でも無限大でもないときに限る、と覚えておきましょう。'],
      ['相関が強ければ、一方が原因で、もう一方が結果だといえるの?', 'いえません。相関は「一緒に増える(減る)傾向」を表すだけで、原因と結果の関係(因果関係)までは示しません。たとえば、アイスの売り上げと水難事故の数には正の相関がありますが、アイスが事故の原因ではなく、どちらも「気温が高い」ことが共通の原因だと考えられます。このような共通の原因を【第3の変数】(交絡因子)といいます。']
    ]
  });

  add('m_h3', {
    secs: [
      { h: 'さらに深く:「わって重なりを消す」が使えるとき・使えないとき', t: '円順列を (n − 1)! と数えるのは、n 人の1列の並び n! 通りの中で、【回転すると同じになる並びが、どれもちょうど n 個ずつ】あるからです。n! を n でわれば、重なりが消えます。じゅず順列(裏返しても同じとみなす)は、さらに裏返しで2個ずつ重なるので、(n − 1)!/2 です。\nここで大切なのは、【すべての並びが同じ個数ずつ重なっているときにだけ、わり算が使える】ということです。\n例:赤玉2個・白玉2個を円形に並べる(回転して同じものは1通り)。1列の並びは 4!/(2!2!) = 6 通りです。これを 4 でわると 1.5 となり、整数になりません。\nなぜでしょうか。「赤赤白白」を回転すると、赤赤白白・赤白白赤・白白赤赤・白赤赤白の4つが重なります。ところが「赤白赤白」は、回転すると赤白赤白・白赤白赤の2つしか現れません(2回まわすと元にもどる)。重なりの個数がそろっていないので、わり算できないのです。正しくは、書き出して「赤どうしが隣り合う」「赤どうしが向かい合う」の 2 通りです。\n同じものをふくむ円順列は、このように【1つを固定する】【書き出す】方が確実です。数が少ない色の玉を1つ固定し、残りの玉の位置関係(となり・向かい側など)で分けると、もれなく数えられます。\n「わる」のは、ていねいに書き出したときの重なり方が全部そろっている、と言えるときだけ、と覚えておきましょう。', key: 'わり算で重なりを消せるのは、すべての並びが同じ個数ずつ重なるときだけ。同じものをふくむ円順列は、固定や書き出しで数える。', ex: [{ q: '白玉3個と黒玉3個を円形に並べる方法は何通りあるか(回転して重なるものは同じとみなす)。', hint: '1列の並び 20 通りを 6 でわると整数にならない。白玉の配置で場合を分ける。', steps: ['1列の並びは 6!/(3!3!) = 20 通りですが、20 ÷ 6 は整数にならないので、わり算は使えません。白黒が交互の並びは、回転して2種類しか現れないからです。', '白玉3個がどう固まっているかで分けます。①3個がすべて隣り合う(白白白黒黒黒)。', '②2個だけ隣り合い、1個が離れている。このとき、離れた1個の白玉の両側は黒で、黒3個は「2個と1個」に分かれます。白白黒白黒黒 と 白白黒黒白黒 は、回転しても重なりません(裏返すと重なるので、じゅず順列なら同じになります)。これで 2 通り。', '③3個がどれも隣り合わない(白黒白黒白黒の交互)。1通りです。合計 1 + 2 + 1 = 4 通りです。'], a: '4 通り', check: '別の確かめ方:回転で重なる仲間に分けると、20 = 6 + 6 + 6 + 2(交互の並びだけ2個の仲間)となり、仲間の数は 4 つです。わり算できない理由が、この「2」にあることが分かります。' }] },
      { h: '実戦演習:だれも自分のものを受け取らない(完全順列)', t: '「5人がプレゼントを1つずつ持ち寄って交換するとき、だれも自分のプレゼントを受け取らない方法は何通りか」という問題は、【完全順列】(かく乱順列)とよばれる入試の定番です。\n戦略は2つあります。1つは【余事象と包除原理】で、「少なくとも1人が自分のものを受け取る」場合を、足しすぎ・引きすぎに注意して数えます。もう1つは【小さい人数から順に考える】方法で、2人なら1通り、3人なら2通り、4人なら9通りと積み上げます。\n落とし穴は、「1人目が自分以外を受け取る方法は 4 通り、2人目も……」と単純にかけ算してしまうことです。前の人の受け取り方によって、次の人の選べる数が変わるので、かけ算では数えられません。', key: '完全順列は包除原理で「1人以上が自分のもの」を数えて引く。単純なかけ算はできない。', ex: [{ q: '5人が自分のプレゼントを1つずつ出し、1人1つずつ受け取る。だれも自分のプレゼントを受け取らない受け取り方は何通りか。', hint: '全体 5! から、「少なくとも1人が自分のものを受け取る」場合を包除原理で引く。', steps: ['受け取り方は全部で 5! = 120 通りです。i さんが自分のものを受け取る場合の集合を A_i とし、A_1 から A_5 の和集合の個数を求めます。', '特定の1人が自分のものを受け取る場合は、残り4人が自由なので 4! = 24 通り。1人の選び方が 5C1 = 5 通りで、合計 120。', '特定の2人なら 3! = 6 通りで、2人の選び方 5C2 = 10 より 60。3人なら 2! × 5C3 = 20、4人なら 1 × 5 = 5、5人全員なら 1 です。', '包除原理より、和集合の個数は 120 − 60 + 20 − 5 + 1 = 76。だれも自分のものを受け取らないのは 120 − 76 = 44 通りです。'], a: '44 通り', check: '小さい人数で確かめると、同じ計算で 3人なら 6 − 6 + 3 − 1 = 2 通り、4人なら 24 − 24 + 12 − 4 + 1 = 9 通りです。3人の 2 通り(BCA、CAB 型)は、書き出しても確かめられます。' }, { q: '1、2、3、4、5 の5つの数字を1列に並べるとき、1 が1番目でなく、かつ 2 が2番目でない並べ方は何通りか。', hint: '「1 が1番目」と「2 が2番目」の和集合を引く。', steps: ['全体は 5! = 120 通りです。', '1 が1番目の並べ方は、残り4つを並べて 4! = 24 通り。2 が2番目も 24 通りです。', '両方が起こる(1 が1番目かつ 2 が2番目)のは、残り3つを並べて 3! = 6 通りです。', '「1 が1番目 または 2 が2番目」は 24 + 24 − 6 = 42 通り。求める数は 120 − 42 = 78 通りです。'], a: '78 通り', check: '直接数える別解:1番目に 2 を置くと残り4つは自由で 24 通り。1番目に 3、4、5 のどれか(3通り)を置くと、2番目に 2 以外の3通り、残り3つで 3! = 6 通りなので 3 × 3 × 6 = 54 通り。合計 78 通りで一致します。' }] }
    ],
    drill: [
      { lv: 2, q: '異なる8個の玉にひもを通して、首飾りをつくる方法は何通りか。', a: '2520 通り', exp: '首飾りは、回転して同じになるものだけでなく、裏返して同じになるものも同じとみなす【じゅず順列】です。円順列は (8 − 1)! = 5040 通りで、裏返すと重なる2つずつの組になっています。8個がすべて異なるので、どの並びも裏返すと必ず別の並びになり、重なりがちょうど2個ずつにそろいます。だから 5040 ÷ 2 = 2520 通りです。左右対称な並びがありうる場合(同じ玉をふくむ場合など)は、裏返しても自分自身と重なる並びがあり、2 でわれないことがあるので注意しましょう。' },
      { lv: 3, q: '6人がプレゼント交換をするとき、ちょうど2人だけが自分のプレゼントを受け取る受け取り方は何通りか。', a: '135 通り', exp: '自分のものを受け取る2人の選び方は 6C2 = 15 通りです。残りの4人は、だれも自分のものを受け取ってはいけない(受け取ると「ちょうど2人」でなくなる)ので、4人の完全順列 9 通りです。9 通りは、4! − 4C1 × 3! + 4C2 × 2! − 4C3 × 1! + 1 = 24 − 24 + 12 − 4 + 1 = 9 で求められます。よって 15 × 9 = 135 通りです。「残り4人は自由に」と考えて 15 × 4! = 360 とすると、3人以上が自分のものを受け取る場合までふくんでしまいます。' },
      { lv: 3, q: '赤玉2個と白玉4個を円形に並べる方法は何通りあるか(回転して重なるものは同じとみなす)。', a: '3 通り', exp: '1列の並びは 6!/(2!4!) = 15 通りですが、15 ÷ 6 = 2.5 は整数にならないので、わり算は使えません。赤玉の1つを固定して、もう1つの赤玉の位置を考えます。固定した赤玉から時計回りに 1、2、3、4、5 番目の位置がありますが、1番目と5番目は「となり」で、回転すると同じ配置です。2番目と4番目も「1つおいて」で同じ配置です。3番目は「向かい側」です。だから「となり」「1つおき」「向かい側」の 3 通りです。向かい側の配置は、回転して重なる並びが3個しかないため、わり算がずれる原因になっています。' }
    ],
    faq: [
      ['包除原理(足して引いて足す)は、なぜ正しいの?', '3つの集合なら、n(A) + n(B) + n(C) で、2つの集合に入る要素は2回、3つすべてに入る要素は3回数えています。2つずつの共通部分を引くと、2つに入る要素は 2 − 1 = 1 回にもどりますが、3つすべてに入る要素は 3 − 3 = 0 回になってしまいます。そこで3つの共通部分を足しもどすと、ちょうど1回ずつになります。どの要素も最後に1回だけ数えられることを確かめるのが、証明の考え方です。'],
      ['円順列の (n − 1)! は、「1人を固定する」と「n でわる」のどちらで考えればいいの?', 'どちらも同じ答えになりますが、「1人を固定する」方がまちがいにくいです。「n でわる」は、すべての並びが n 個ずつ重なるという前提があり、同じものをふくむときにはその前提がくずれます。「固定する」考え方なら、固定した人から見た残りの並びを数えるだけなので、条件つきの円順列(特定の2人が向かい合うなど)にもそのまま使えます。']
    ]
  });

  add('m_prob', {
    secs: [
      { h: 'さらに深く:期待値は「1つずつに分けて足す」と楽になる', t: '期待値には、とても便利な性質があります。【和の期待値は、期待値の和】、つまり E(X + Y) = E(X) + E(Y) です。X と Y が独立でなくても、いつでも成り立ちます。\nこれを使うと、数えにくい量の期待値を、【「〜なら 1、そうでなければ 0」という量の和】に分けて求められます。\n例:サイコロを3回ふるとき、「出た目の種類の数」の期待値。直接だと、1種類・2種類・3種類になる確率をそれぞれ求める必要があります。\nそこで、目 1 について「3回のうち少なくとも1回出たら 1、出なければ 0」という量 X₁ を考えます。目 2〜6 についても同じく X₂〜X₆ を作ると、【目の種類の数 = X₁ + X₂ + … + X₆】です。\nX₁ の期待値は、1 × (1 が少なくとも1回出る確率) + 0 × (出ない確率) = 1 − (5/6)³ = 91/216。どの目も同じなので、求める期待値は 6 × 91/216 = 91/36(約 2.53)です。\n直接求めても確かめられます。1種類になる確率は 6/216、2種類は 90/216、3種類は 120/216 で、1 × 6 + 2 × 90 + 3 × 120 = 546、546/216 = 91/36 です。\nこの方法のよさは、X₁ と X₂ が独立でなくてもよいことです(1 が出ると 2 が出にくくなる、という関係があってもかまいません)。「全体を、0 か 1 の小さな量の和に分ける」と考えると、入試の期待値の問題がぐっと楽になります。', key: '期待値は、和に分けて別々に求めて足してよい。数えにくい量は「起これば 1、起こらなければ 0」の和に分解する。', ex: [{ q: '大小2つのサイコロを投げるとき、出た目の差(大きい方 − 小さい方、同じなら 0)の期待値を求めよう。', hint: '差が 0、1、2、3、4、5 になる場合の数を表で数える。', steps: ['36 通りの (大, 小) の組を表にし、差 |a − b| ごとに数えます。差 0 は 6 通り、差 1 は 10 通り、差 2 は 8 通り、差 3 は 6 通り、差 4 は 4 通り、差 5 は 2 通りです。', '合計が 6 + 10 + 8 + 6 + 4 + 2 = 36 で、もれがないことを確かめます。', '期待値は (0 × 6 + 1 × 10 + 2 × 8 + 3 × 6 + 4 × 4 + 5 × 2)/36 = (10 + 16 + 18 + 16 + 10)/36 = 70/36 です。', '約分して 35/18(約 1.94)です。'], a: '35/18', check: '差 k(1 ≦ k ≦ 5)になる組は、「小さい方」が 1 から 6 − k の (6 − k) 通りで、大小の入れかえで2倍の 2(6 − k) 通りです。k = 1 なら 10 通りで、表の結果と一致します。' }] },
      { h: '実戦演習:途中の条件がつく確率', t: '「途中で一度も〜にならない確率」のように、【最後の結果だけでなく、途中の様子にも条件】がつく問題は、反復試行の公式 nCk pᵏ(1 − p)ⁿ⁻ᵏ だけでは解けません。\n戦略は、点の動きを【経路(格子の道)】として図にすることです。縦軸に位置、横軸に回数をとると、1回ごとに右上か右下に進む折れ線になります。条件を満たす経路の数を数え、1本の経路の確率をかけます。\n数えにくいときは、条件を破る経路を数えて全体から引く(余事象)と楽になります。「位置 −1 に一度でも触れる経路」は、触れた点から先を上下反対に折り返すと、別の簡単な経路と1対1に対応します(反射の考え方)。', key: '途中の条件は経路の図で数える。条件を破る経路は、折り返して別の経路と対応させると数えやすい。', ex: [{ q: '数直線上の原点に点 P がある。コインを投げて表なら +1、裏なら −1 だけ P を動かす。6回投げたとき、P が一度も負の位置に行かずに、最後に +2 の位置にある確率を求めよう。', hint: '+2 で終わる経路は表4回・裏2回。そのうち −1 に触れる経路を折り返しで数える。', steps: ['6回後に +2 にいるのは、表4回・裏2回のときで、その並び方は 6C2 = 15 通りです。', 'このうち、途中で一度でも −1 に触れる経路を数えます。初めて −1 に触れた時点から後の動きを上下反対にすると、最後の位置は +2 から −1 について折り返した −4 になります。', '−4 で終わる経路は表1回・裏5回で 6C1 = 6 通りです。この対応は1対1なので、−1 に触れる経路も 6 通りです。', '条件を満たす経路は 15 − 6 = 9 通り。1つの経路の確率は (1/2)⁶ なので、求める確率は 9/64 です。'], a: '9/64', check: '書き出しでも確かめられます。最初は必ず表です(裏だと −1)。表表で始まると位置は +2 なので、残り4回(表2裏2)はどう並べても負になりません。これで 4C2 = 6 通り。表裏で始まると位置は 0 なので3回目は表が必要で、そのあとの3回(表2裏1)は、どう並べても負になりません。これで 3 通り。合計 9 通りで一致します。' }, { q: 'サイコロを3回ふるとき、出た目の積が 4 の倍数になる確率を求めよう。', hint: '余事象「4 の倍数でない」を、2 の因数の個数で分けて数える。', steps: ['積が 4 の倍数でないのは、積にふくまれる 2 の個数が 0 個か 1 個のときです。', '2 の個数が 0 個:3回とも奇数の目(1、3、5)で 3³ = 27 通り。', '2 の個数がちょうど 1 個:1回だけ 2 か 6(どちらも 2 を1個だけふくむ)が出て、残り2回が奇数です。どの回に出るかが3通り、目が2通り、奇数が 3² 通りで 3 × 2 × 9 = 54 通り。4 の目は 2 を2個ふくむので、ここには入りません。', '4 の倍数でないのは 27 + 54 = 81 通り。求める確率は 1 − 81/216 = 135/216 = 5/8 です。'], a: '5/8', check: '「偶数が2回以上出れば4の倍数」だけを数えると、4 の目が1回だけ出る場合(たとえば 4、1、3)を落とします。2 の個数で分けると、4 の目の特別さを見落としません。' }] }
    ],
    drill: [
      { lv: 2, q: '1 から 10 までの番号のついたカード10枚から、3枚を同時に引く。引いたカードの番号の和の期待値を求めよう。', a: '33/2(16.5)', exp: '3枚を、引いた後に1枚目・2枚目・3枚目と区別して考えると、番号の和 = (1枚目の番号) + (2枚目の番号) + (3枚目の番号) です。どの1枚も、10枚のどれである確率も 1/10 ずつなので、1枚の番号の期待値は (1 + 2 + … + 10)/10 = 11/2 です。和の期待値は期待値の和なので、3 × 11/2 = 33/2 です。3枚の番号は同じ番号にならない(独立ではない)のですが、期待値の和の性質は独立でなくても使えます。和の分布を 10C3 = 120 通りすべて調べなくても、一瞬で答えが出ます。' },
      { lv: 3, q: 'n 人がプレゼント交換をし、受け取り方がすべて同様に確からしいとする。自分のプレゼントを受け取る人数の期待値を求めよう。', a: '1(人数 n によらない)', exp: 'i 番目の人について、「自分のものを受け取れば 1、そうでなければ 0」という量 Xᵢ を考えると、自分のものを受け取る人数は X₁ + X₂ + … + Xₙ です。i 番目の人が自分のものを受け取る確率は、n 個のプレゼントのうち特定の1つが当たる確率で 1/n なので、Xᵢ の期待値は 1/n です。和の期待値は期待値の和なので、n × 1/n = 1 です。Xᵢ どうしは独立ではありません(n − 1 人が自分のものを受け取れば、最後の人も必ず自分のものになる)が、期待値の和の性質は独立でなくても使えます。人数が何人でも期待値は 1 人、というのは意外で面白い結果です。' },
      { lv: 3, q: 'サイコロを4回ふるとき、出た目の積が 6 の倍数になる確率を求めよう。', a: '325/432', exp: '6 の倍数 ⇔ 2 の倍数 かつ 3 の倍数、です。余事象「6 の倍数でない」は、「偶数が1回も出ない」または「3 の倍数が1回も出ない」です。偶数が出ない(1、3、5 だけ)確率は (1/2)⁴ = 1/16、3 の倍数が出ない(1、2、4、5 だけ)確率は (2/3)⁴ = 16/81、両方(1、5 だけ)は (1/3)⁴ = 1/81。和事象の確率は 1/16 + 16/81 − 1/81 = 1/16 + 15/81 = 1/16 + 5/27 = 107/432。求める確率は 1 − 107/432 = 325/432 です。「または」の余事象で、共通部分を引き忘れないことがポイントです。' }
    ],
    faq: [
      ['期待値は、「いちばん起こりやすい値」のことなの?', 'いいえ。期待値は「同じ試行を何回もくり返したときの平均の値」です。たとえば、サイコロの目の期待値は 3.5 ですが、3.5 の目は出ません。また、宝くじの賞金の期待値が 100 円でも、ほとんどの人は 0 円で、ごく一部の人が大きな賞金を得ます。いちばん起こりやすい値(最頻値)と期待値は、別のものとして区別しましょう。'],
      ['「途中で〜にならない」問題は、いつも折り返しで数えるの?', '折り返し(反射)が使えるのは、+1 と −1 のように上下対称に動く場合で、「ある線に触れる」という条件のときです。回数が少なければ、樹形図や「各時点の位置ごとに経路の数を書きこむ表」で数える方が確実です。格子の各点に、そこへ来る経路の数を左から順に足して書いていく方法は、どんな条件にも使える万能の方法です。']
    ]
  });

  add('ma_cond', {
    secs: [
      { h: 'さらに深く:直感とずれる条件付き確率(3つの扉の問題)', t: '条件付き確率は、直感と答えがずれやすいことで有名です。代表が【3つの扉の問題】(モンティ・ホール問題)です。\n3つの扉の1つの後ろに賞品があり、残り2つははずれです。あなたが扉 1 を選ぶと、答えを知っている司会者が、残りの扉のうち【はずれの扉を1つ】開けて見せます(2つともはずれなら、どちらかを同じ確率で開けます)。ここで「扉を変えますか?」と聞かれます。\n多くの人は「残りは2つだから、どちらも 1/2」と考えます。しかし、正しくは【変えると当たる確率は 2/3】です。\n理由を、場合を分けて考えます。賞品が扉 1、2、3 にある確率はどれも 1/3 です。\n・賞品が扉 1:司会者は扉 2 か 3 を開ける。変えるとはずれ。\n・賞品が扉 2:司会者は扉 3 しか開けられない。変えると当たり。\n・賞品が扉 3:司会者は扉 2 しか開けられない。変えると当たり。\n3つのうち2つの場合で、変えると当たります。\n条件付き確率で書くと、「司会者が扉 3 を開けた」という条件のもとで考えます。P(扉 3 を開ける) は、賞品が扉 1 のとき 1/3 × 1/2 = 1/6、扉 2 のとき 1/3 × 1 = 1/3 で、合計 1/2。そのうち賞品が扉 2 なのは 1/3 なので、(1/3) ÷ (1/2) = 2/3 です。\nポイントは、司会者の行動が【ランダムではなく、賞品の位置に左右されている】ことです。「はずれを選んで開けた」という情報が、残りの扉の確率を変えたのです。もし司会者が答えを知らずに偶然はずれを開けたのなら、確率は本当に 1/2 ずつになります。', key: '条件付き確率では、「その情報がどのようにして得られたか」まで考える。情報の出方が原因に左右されると、確率は変わる。', ex: [{ q: '3つの扉の問題で、司会者がはずれの扉 3 を開けたとき、扉 2 に変えた場合に当たる確率を、条件付き確率の式で求めよう。', hint: 'P(扉2に賞品 | 扉3を開けた) = P(扉2に賞品 かつ 扉3を開けた) ÷ P(扉3を開けた)', steps: ['賞品の位置が扉 1、2、3 である確率はそれぞれ 1/3。あなたは扉 1 を選んでいます。', '司会者が扉 3 を開ける確率を、賞品の位置で分けて求めます。扉 1 なら 2 か 3 を半分ずつで 1/3 × 1/2 = 1/6。扉 2 なら 3 を必ず開けるので 1/3 × 1 = 1/3。扉 3 なら開けないので 0。合計 1/6 + 1/3 = 1/2 です。', '「扉 2 に賞品 かつ 扉 3 を開けた」確率は 1/3 です。', 'よって求める確率は (1/3) ÷ (1/2) = 2/3。変えない場合(扉 1 が当たり)は (1/6) ÷ (1/2) = 1/3 です。'], a: '2/3', check: '扉が 100 個あり、司会者がはずれを 98 個開けて、あなたの扉と1つの扉だけが残る、と考えると直感的です。最初の選択が当たっている確率は 1/100 のままなので、残った1つに変えると 99/100 で当たります。' }] },
      { h: '実戦演習:取り出した玉を別の袋に移す問題', t: '「袋 A から玉を取り出して袋 B に入れ、袋 B から玉を取り出したら赤だった。移した玉が赤だった確率は?」という問題は、原因の確率の応用です。\n戦略は、【1段目(移す玉)で場合を分け、それぞれの場合の2段目(取り出す玉)の確率をかける】ことです。1段目の結果によって、袋 B の中身が変わるので、2段目の確率もそれに合わせて計算し直します。\n樹形図をかき、「結果が赤になる枝」だけを全部集めて分母にし、そのうち求めたい枝を分子にします。落とし穴は、袋 B の玉の総数が1個増えていることを忘れることです。', key: '1段目の結果で2段目の袋の中身が変わる。樹形図で「結果が起こる枝」をすべて集めて分母にする。', ex: [{ q: '袋 A には赤玉3個・白玉2個、袋 B には赤玉1個・白玉3個が入っている。袋 A から1個取り出して袋 B に入れ、よくまぜてから袋 B から1個取り出したら赤玉だった。袋 A から移した玉が赤玉だった確率を求めよう。', hint: '移した玉が赤なら B は赤2白3、白なら赤1白4。', steps: ['移した玉が赤である確率は 3/5。このとき袋 B は赤2個・白3個の5個になり、B から赤を取り出す確率は 2/5。この枝の確率は 3/5 × 2/5 = 6/25 です。', '移した玉が白である確率は 2/5。このとき袋 B は赤1個・白4個で、赤を取り出す確率は 1/5。この枝の確率は 2/5 × 1/5 = 2/25 です。', 'B から赤を取り出す確率は、この2つの枝の和で 6/25 + 2/25 = 8/25 です。', '求める確率は (6/25) ÷ (8/25) = 6/8 = 3/4 です。'], a: '3/4', check: '取り出す前の「移した玉が赤」の確率 3/5 = 0.6 より、赤が出たと分かった後の確率 3/4 = 0.75 の方が大きくなっています。赤を移すと B の赤が増えるので、「赤が出た」という結果は「赤を移した」ことの証拠になる、という直感と合っています。' }] }
    ],
    drill: [
      { lv: 2, q: '大小2つのサイコロを投げたところ、目の和が 8 だった。このとき、少なくとも一方の目が 6 である確率を求めよう。', a: '2/5', exp: '目の和が 8 になる組は、(大, 小) = (2, 6)、(3, 5)、(4, 4)、(5, 3)、(6, 2) の 5 通りです。条件付き確率では、全体がこの 5 通りにしぼられます。このうち少なくとも一方が 6 なのは (2, 6) と (6, 2) の 2 通りなので、2/5 です。条件がなければ「少なくとも一方が 6」の確率は 11/36(約 0.31)ですが、「和が 8」という条件で 0.4 に変わりました。(4, 4) を1通り、(3, 5) と (5, 3) を2通りと数えることに注意しましょう。大小を区別した 36 通りが同様に確からしいからです。' },
      { lv: 3, q: '4つの扉の1つの後ろに賞品がある。あなたが扉を1つ選ぶと、答えを知っている司会者が、残りの扉のうちはずれの扉を1つ開ける。あなたが、開いていない別の2つの扉のどちらかに、同じ確率で選び直すとき、当たる確率を求めよう。', a: '3/8', exp: '最初に選んだ扉が当たりの確率は 1/4 で、このときは選び直すと必ずはずれます。最初の扉がはずれの確率は 3/4 です。このとき、司会者はもう1つのはずれを開けるので、残った2つの扉のうち1つが当たりです。そこから同じ確率で選ぶので、当たる確率は 1/2。よって 3/4 × 1/2 = 3/8 です。選び直さない場合の 1/4 = 2/8 より大きいので、扉が4つでも選び直す方が有利です。3つの扉で 2/3 になったのは、選び直す先が1つしかなかったからです。' },
      { lv: 3, q: '袋 A には赤玉2個・白玉2個、袋 B には赤玉1個・白玉1個が入っている。袋 A から2個を同時に取り出して袋 B に入れ、袋 B から1個取り出したら赤玉だった。袋 A から移した2個がどちらも赤玉だった確率を求めよう。', a: '1/4', exp: '移す2個の組合せは 4C2 = 6 通りで、赤赤が 1 通り、赤白が 4 通り、白白が 1 通りです。赤赤(確率 1/6)なら B は赤3白1で、赤を取る確率 3/4、枝の確率 1/8。赤白(4/6)なら B は赤2白2で 1/2、枝の確率 1/3。白白(1/6)なら B は赤1白3で 1/4、枝の確率 1/24。赤を取り出す確率は 1/8 + 1/3 + 1/24 = 3/24 + 8/24 + 1/24 = 1/2 です。求める確率は (1/8) ÷ (1/2) = 1/4 です。B の玉が 4 個になっていることを忘れず、場合ごとに計算し直すのがポイントです。' }
    ],
    faq: [
      ['条件付き確率は、時間の順番と関係あるの?', '関係ありません。P_A(B) の A は「分かっている情報」であって、「先に起こったこと」とは限りません。「2回目に赤が出たと分かったとき、1回目が赤である確率」のように、あとの結果を条件にして前のことを考えてもかまいません。原因の確率は、まさにこの形です。大切なのは時間ではなく、「どの場合に全体をしぼるか」です。'],
      ['「同時に2個取り出す」と「1個ずつ戻さずに2回取り出す」は、同じように扱っていいの?', '何色が出るかという結果だけを問題にするなら、同じ確率になります。「同時に取り出す」は「1個ずつ戻さずに取り出して、順番を忘れる」ことと同じだからです。たとえば赤3白2から2個とも赤の確率は、同時なら 3C2/5C2 = 3/10、順番に取り出すなら 3/5 × 2/4 = 3/10 で一致します。条件付き確率で考えたいときは、順番に取り出すと考える方が乗法定理を使いやすく便利です。']
    ]
  });
  add('ma_geo', {
    secs: [
      { h: 'さらに深く:4点が同じ円の上にあると見ぬく(円周角の定理の逆)', t: '円周角の定理は「同じ弧に対する円周角は等しい」でした。実は、この【逆】も成り立ちます。\n【円周角の定理の逆】2点 P、Q が直線 AB について同じ側にあり、∠APB = ∠AQB ならば、4点 A、B、P、Q は1つの円の上にある。\n【円に内接する四角形の条件】四角形の向かい合う角の和が 180°(または、1つの内角がその対角の外角と等しい)ならば、その四角形は円に内接する。\nこれを使うと、図の中に【隠れた円】を見つけられます。円が見つかれば、円周角の定理を使って、離れた場所の角を一気に移せます。\nとくによく使うのが、【直角が2つ並んでいる形】です。∠APB = ∠AQB = 90° なら、P と Q は AB を直径とする円の上にあります(直径に対する円周角が 90° であることの逆)。\n例:鋭角三角形 ABC で、B から辺 CA に下ろした垂線の足を E、C から辺 AB に下ろした垂線の足を F とします。∠BEC = ∠BFC = 90° で、E と F は直線 BC について同じ側にあるので、4点 B、C、E、F は【BC を直径とする円】の上にあります。\nすると四角形 BCEF は円に内接するので、E での外角 ∠AEF は、向かい合う角 ∠FBC = ∠ABC に等しくなります。∠ABC = 70° なら ∠AEF = 70° です。\nこのことから、三角形 AEF と三角形 ABC は、∠A が共通で ∠AEF = ∠ABC なので【相似】だと分かります。垂線の足を結んだ三角形が、もとの三角形と(向きを変えて)相似になるという、入試でよく使う事実です。', key: '直角が2つ並んでいたり、等しい角が同じ側に並んでいたりしたら、隠れた円を疑う。円が見つかれば、円周角で角を移せる。', ex: [{ q: '鋭角三角形 ABC で、∠ABC = 65°、∠ACB = 50° とする。頂点 A から辺 BC に下ろした垂線の足を D、頂点 B から辺 CA に下ろした垂線の足を E とするとき、∠ADE の大きさを求めよう。', hint: '∠ADB = ∠AEB = 90° なので、4点 A、B、D、E は AB を直径とする円の上にある。', steps: ['∠BAC = 180° − 65° − 50° = 65° です。', '∠ADB = 90°、∠AEB = 90° で、D と E は直線 AB について同じ側にあるので、4点 A、B、D、E は AB を直径とする円の上にあります。', 'この円で、∠ADE と ∠ABE は同じ弧 AE に対する円周角なので等しくなります。', '直角三角形 ABE で、∠ABE = 90° − ∠BAE = 90° − 65° = 25°。よって ∠ADE = 25° です。'], a: '25°', check: '別の見方:四角形 ABDE は円に内接するので、D での外角 ∠EDC は対角 ∠BAE = 65° に等しくなります。∠ADC = 90° なので ∠ADE = 90° − 65° = 25° となり、一致します。' }] },
      { h: '実戦演習:2つの円の共通接線の長さ', t: '2つの円に同時に接する直線を【共通接線】といいます。共通接線の長さ(2つの接点の間の距離)は、【中心を結ぶ線分】と【半径】で直角三角形を作れば求められます。\n戦略:①2つの中心 O、O′ と接点 A、B をかき、半径 OA、O′B が接線に垂直であることを確認する ②O′ から OA(またはその延長)に垂線を下ろし、長方形と直角三角形に分ける ③三平方の定理を使う。\n共通外接線(2つの円が接線の同じ側にある)なら、直角三角形の1辺は【半径の差】、共通内接線(接線をはさんで反対側にある)なら【半径の和】になります。この使い分けが差のつくところです。', key: '半径は接線に垂直。中心どうしの距離を斜辺とする直角三角形を作り、外接線は半径の差、内接線は半径の和を使う。', ex: [{ q: '半径 5 の円 O と半径 2 の円 O′ があり、中心間の距離は OO′ = 9 である。共通外接線の長さと、共通内接線の長さを求めよう。', hint: '外接線:斜辺 9、1辺 5 − 2 = 3。内接線:斜辺 9、1辺 5 + 2 = 7。', steps: ['共通外接線が円 O、O′ と接する点を A、B とします。OA ⊥ AB、O′B ⊥ AB なので、OA と O′B は平行です。', 'O′ から OA に垂線 O′H を下ろすと、四角形 HABO′ は長方形で、AB = HO′、AH = BO′ = 2 です。よって OH = 5 − 2 = 3。直角三角形 OHO′ で HO′ = √(9² − 3²) = √72 = 6√2 です。', '共通内接線では、接点を C、D とすると、OC と O′D は接線をはさんで反対向きです。O′ から OC の延長に垂線を下ろすと、OH = 5 + 2 = 7 になります。', '直角三角形で √(9² − 7²) = √32 = 4√2 です。'], a: '共通外接線の長さ 6√2、共通内接線の長さ 4√2', check: '中心間の距離 9 が半径の和 7 より大きいので、2つの円は離れていて、共通接線は外接線2本・内接線2本の計4本あります。内接線の計算で √ の中が正になったことも、そのことと合っています。' }] }
    ],
    drill: [
      { lv: 2, q: '半径 4 の円と半径 6 の円が、異なる2点で交わるような中心間の距離 d の範囲を求めよう。', a: '2 < d < 10', exp: '2つの円の位置関係は、中心間の距離 d と、半径の和(10)・差(2)の大小で決まります。d > 10 なら離れている、d = 10 なら外側で接する、2 < d < 10 なら2点で交わる、d = 2 なら内側で接する、d < 2 なら一方が他方の内部にあります。2点で交わるときは、2つの中心と1つの交点で三角形ができ、その3辺が 4、6、d なので、三角形ができる条件(どの2辺の和も残りの1辺より大きい)6 − 4 < d < 6 + 4 と同じ式になります。' },
      { lv: 3, q: '半径 4 の円と半径 9 の円が外側で接している。この2つの円の共通外接線の長さ(2つの接点の距離)を求めよう。', a: '12', exp: '外側で接しているので、中心間の距離は半径の和で 4 + 9 = 13 です。共通外接線の長さは、斜辺 13、1辺が半径の差 9 − 4 = 5 の直角三角形の残りの辺なので、√(13² − 5²) = √144 = 12 です。一般に、半径 r、R の2円が外接するとき、共通外接線の長さは √((R + r)² − (R − r)²) = √(4Rr) = 2√(Rr) となります。2√(4 × 9) = 12 で確かめられます。この形は、2つの円の間に3つ目の円をはさむ問題でよく使います。' },
      { lv: 3, q: '鋭角三角形 ABC で、頂点 B から辺 CA に下ろした垂線の足を E、頂点 C から辺 AB に下ろした垂線の足を F とする。AB = 6、AC = 5、AE = 3 のとき、AF の長さを求めよう。', a: 'AF = 5/2', exp: '∠BEC = ∠BFC = 90° なので、4点 B、C、E、F は BC を直径とする円の上にあります。四角形 BCEF は円に内接するので、∠AEF = ∠ABC、∠AFE = ∠ACB です。よって三角形 AEF と三角形 ABC は相似で、AE と AB、AF と AC が対応します。AE : AB = AF : AC から 3 : 6 = AF : 5、AF = 5/2 です。方べきの定理(A から見て AF × AB = AE × AC)を使っても、AF × 6 = 3 × 5 から AF = 5/2 と求められます。直角三角形 ABE で cos A = 3/6 = 1/2、直角三角形 ACF で AF = 5 × cos A = 5/2 となり、三角比でも一致します。' }
    ],
    faq: [
      ['4点が同じ円の上にあるかどうか、どうやって確かめればいいの?', '主な方法は3つです。①ある線分を見こむ角が、同じ側の2点から等しい(円周角の定理の逆)。②四角形の対角の和が 180°。③方べきの定理の逆(2直線の交点 P について PA × PB = PC × PD)。とくに、「90° が2つある」ときは①の特別な場合で、直径を見つけるのが近道です。どれも、図の中の角や長さの関係を確かめるだけなので、円をかかなくても判断できます。'],
      ['2つの円の共通接線は、何本あるの?', '位置関係で決まります。離れているとき4本(外接線2本・内接線2本)、外側で接するとき3本(接点を通る接線が1本加わり、内接線2本が1本にまとまる)、2点で交わるとき2本(外接線だけ)、内側で接するとき1本、一方が他方の内部にあるとき0本です。中心間の距離 d と、半径の和・差を比べると、どれに当たるかが分かります。']
    ]
  });

  add('ma_ceva', {
    secs: [
      { h: 'さらに深く:チェバの定理の逆で「1点で交わる」を証明する', t: 'チェバの定理には【逆】があります。\n【チェバの定理の逆】△ABC の辺 BC、CA、AB 上にそれぞれ点 D、E、F があり、(AF/FB) × (BD/DC) × (CE/EA) = 1 が成り立つならば、3直線 AD、BE、CF は1点で交わる。\n証明の考え方:AD と BE の交点を P とし、直線 CP と AB の交点を F′ とします。チェバの定理から (AF′/F′B) × (BD/DC) × (CE/EA) = 1。仮定の式と比べると AF′/F′B = AF/FB となり、AB を同じ比に内分する点は1つしかないので F′ = F。だから CF も P を通ります。\nこの逆を使うと、「三角形の3本の〇〇は1点で交わる」という事実が、比の計算だけで証明できます。\n例1(重心):中線なら、どの点も辺の中点なので、比はすべて 1 で、1 × 1 × 1 = 1。だから3本の中線は1点で交わります。\n例2(内心):角の二等分線の定理より、BD/DC = AB/AC = c/b、CE/EA = BC/BA = a/c、AF/FB = CA/CB = b/a。かけると (b/a)(c/b)(a/c) = 1 なので、3本の角の二等分線は1点で交わります。\n五心が1点で交わる理由として、ma_geo では「性質をもつ点の集まり」で説明しましたが、チェバの逆を使うと、もう1つの別の証明ができるのです。\n同じように、【メネラウスの定理の逆】を使えば、「3点が一直線上にある」ことを比の計算で示せます。辺の延長上の点がちょうど1個(または3個)あり、比の積が 1 なら、3点は一直線上にあります。', key: '比の積が 1 になることを示せば、3直線が1点で交わる(チェバの逆)、3点が一直線上にある(メネラウスの逆)と証明できる。', ex: [{ q: '△ABC の内部に点 P があり、△PBC、△PCA、△PAB の面積の比が 2 : 3 : 4 である。直線 AP と辺 BC の交点を D とするとき、BD : DC と AP : PD を求めよう。', hint: 'BD : DC = △ABP : △ACP。AP : PD は、△ABC と △PBC の高さの比から。', steps: ['△ABP と △ACP は辺 AP を共通にもちます。B と C から直線 AD までの距離の比は BD : DC に等しいので、BD : DC = △ABP : △ACP = 4 : 3 です。', '次に、△ABC と △PBC は底辺 BC が共通なので、面積の比は高さの比、つまり AD : PD に等しくなります。', '△ABC = 2 + 3 + 4 = 9、△PBC = 2 なので、AD : PD = 9 : 2 です。', 'よって AP : PD = (9 − 2) : 2 = 7 : 2 です。'], a: 'BD : DC = 4 : 3、AP : PD = 7 : 2', check: 'ほかの2辺についても同じように CE : EA = △BCP : △BAP = 2 : 4、AF : FB = △CAP : △CBP = 3 : 2 となります。チェバの式に入れると (3/2) × (4/3) × (2/4) = 1 となり、たしかに3直線が1点 P で交わることと合っています。' }] },
      { h: '実戦演習:3本の線分が作る内側の三角形の面積', t: '△ABC の各辺を同じ比に分ける点と、向かいの頂点を結ぶ3本の線分は、ふつうは1点で交わらず、内側に小さな三角形を作ります。その面積を求める問題は、メネラウスの定理の総合問題です。\n戦略:①1本の線分(たとえば AD)の上に、ほかの2本との交点が2つあるので、それぞれの位置をメネラウスの定理で求める ②【△ABC から、まわりの3つの三角形を引く】と内側の三角形が残る、という見方で面積を計算する ③まわりの三角形は、「底辺の比 × 高さの比」で △ABC の何倍かを出す。\n落とし穴は、まわりの三角形の分け方をまちがえて、重なりやすき間を作ることです。図をかき、「どの3つで全体がちょうど分かれるか」を確かめましょう。', key: '内側の三角形 = 全体 − まわりの3つの三角形。まわりの三角形の面積は、メネラウスで出した線分の比から求める。', ex: [{ q: '△ABC で、辺 BC、CA、AB を 1 : 2 に内分する点をそれぞれ D、E、F とする(BD : DC = CE : EA = AF : FB = 1 : 2)。AD と BE の交点を P、BE と CF の交点を Q、CF と AD の交点を R とするとき、△PQR の面積は △ABC の何倍か。', hint: 'メネラウスで AP : PD を求め、△ABP の面積を出す。図は3回転して同じ形なので、まわりの3つの三角形は同じ面積。', steps: ['△ADC と直線 BE(B、P、E が一直線)にメネラウスの定理を使います。(AP/PD) × (DB/BC) × (CE/EA) = 1 で、DB/BC = 1/3、CE/EA = 1/2 なので、AP/PD = 6。AP : PD = 6 : 1 です。', '△ABD の面積は、BD : BC = 1 : 3 なので △ABC の 1/3。そのうち △ABP は AP : AD = 6 : 7 なので、△ABP = (1/3) × (6/7) = 2/7 倍です。', 'この図形は、A → B → C と回しても同じ条件になっているので、△BCQ、△CAR も同じく 2/7 倍です。△ABC は、△ABP、△BCQ、△CAR と内側の △PQR の4つにちょうど分かれます。', 'よって △PQR = 1 − 3 × 2/7 = 1/7 倍です。'], a: '1/7 倍', check: '座標で確かめます。A(0, 0)、B(1, 0)、C(0, 1) とおいて P、Q、R を計算すると、△PQR の面積は 1/14 で、△ABC の面積 1/2 の 1/7 倍になります。また、△ABD と直線 CF のメネラウスから AR : RD = 3 : 4 も出せて、AD 上で AR : RP : PD = 3 : 3 : 1 と並ぶことも確かめられます。' }] }
    ],
    drill: [
      { lv: 2, q: '△ABC で、辺 AB 上の点 F が AF : FB = 1 : 2、辺 CA 上の点 E が CE : EA = 1 : 2、辺 BC の C の側の延長上の点 D が BD : DC = 4 : 1 を満たす。3点 D、E、F は一直線上にあるか。', a: '一直線上にある', exp: 'メネラウスの定理の逆を使います。頂点と点を交互にたどって A → F → B → D → C → E → A と一周し、比をかけると (AF/FB) × (BD/DC) × (CE/EA) = (1/2) × (4/1) × (1/2) = 1 です。延長上の点(D)がちょうど1個で、比の積が 1 なので、D、E、F は一直線上にあります。もし3点がすべて辺の内部にあると、比の積が 1 になってもそれはチェバの形で、一直線にはなりません。メネラウスの逆を使うときは、「延長上の点が1個か3個」であることを確かめましょう。' },
      { lv: 3, q: '△ABC で、辺 BC、CA、AB を 1 : 3 に内分する点をそれぞれ D、E、F とする(BD : DC = CE : EA = AF : FB = 1 : 3)。3本の線分 AD、BE、CF が作る内側の三角形の面積は、△ABC の何倍か。', a: '4/13 倍', exp: 'AD と BE の交点を P とします。△ADC と直線 BE でメネラウスの定理を使うと、(AP/PD) × (DB/BC) × (CE/EA) = (AP/PD) × (1/4) × (1/3) = 1 から AP : PD = 12 : 1 です。△ABD は △ABC の 1/4 倍、△ABP はその 12/13 なので、△ABP = (1/4) × (12/13) = 3/13 倍。図形は回しても同じ条件なので、まわりの3つの三角形はどれも 3/13 倍で、内側の三角形は 1 − 9/13 = 4/13 倍です。分ける比を 1 : k にすると、内側の三角形は (k − 1)²/(k² + k + 1) 倍になり、k = 2 で 1/7、k = 3 で 4/13 となります。' },
      { lv: 3, q: '△ABC で、角 A、B、C の二等分線と向かいの辺の交点をそれぞれ D、E、F とする。AB = 6、BC = 5、CA = 4 のとき、BD/DC、CE/EA、AF/FB をそれぞれ求め、3本の二等分線が1点で交わることをチェバの定理の逆で確かめよう。', a: 'BD/DC = 3/2、CE/EA = 5/6、AF/FB = 4/5。積は 1 なので1点で交わる。', exp: '角の二等分線の定理より、BD : DC = AB : AC = 6 : 4 = 3 : 2、CE : EA = BC : BA = 5 : 6、AF : FB = CA : CB = 4 : 5 です。(AF/FB) × (BD/DC) × (CE/EA) = (4/5) × (3/2) × (5/6) = 60/60 = 1。D、E、F はすべて辺の内部にあるので、チェバの定理の逆により、3本の二等分線 AD、BE、CF は1点で交わります。この交点が内心です。文字で書けば (b/a)(c/b)(a/c) = 1 となり、どんな三角形でも成り立つことが分かります。' }
    ],
    faq: [
      ['チェバの定理の逆は、どんなときに使うの?', '「3本の直線が1点で交わることを示せ」という証明問題で使います。交点を直接求めなくても、各辺を分ける比をかけて 1 になることを示すだけで証明できるのが強みです。重心・内心のほか、「内接円と各辺の接点と、向かいの頂点を結ぶ3本の線は1点で交わる」ことも、接線の長さが等しいことから比の積が 1 になると示せます。'],
      ['面積の比を求めるとき、比のかけ算のコツは?', '1つの三角形の面積を、【底辺の比 × 高さの比】と2段階に分けて考えることです。たとえば △ABP を求めるなら、まず △ABD が △ABC の何倍か(BD : BC)、次に △ABP が △ABD の何倍か(AP : AD)を出してかけます。一度に求めようとせず、「1つ大きい三角形」を間にはさむと、まちがいが減ります。']
    ]
  });

  add('m_int', {
    secs: [
      { h: 'さらに深く:n! の中に素数 p はいくつふくまれるか', t: '「100! を計算すると、末尾に 0 はいくつ並ぶか」という問題を考えます。100! は 158 けたもある巨大な数ですが、計算しなくても答えが出ます。\n末尾の 0 の個数は、10 で何回わり切れるかです。10 = 2 × 5 なので、100! を素因数分解したときの【2 の個数と 5 の個数のうち、少ない方】が答えです。2 は偶数ごとに出てくるのに対し、5 はあまり出てこないので、5 の個数を数えれば十分です。\n5 の個数の数え方:1 から 100 までのうち、\n・5 の倍数は 100 ÷ 5 = 20 個。それぞれ 5 を少なくとも1個ずつもつ。\n・25 の倍数(25、50、75、100)は 5 を2個もつので、上で数えた1個に加えて、もう1個ずつ数える。100 ÷ 25 = 4 個。\n・125 の倍数は 100 以下にない。\n合計 20 + 4 = 24 個。だから 100! の末尾には 0 が 24 個並びます。\nこのように、【n! にふくまれる素数 p の個数 = [n/p] + [n/p²] + [n/p³] + …】([ ] は小数点以下を切り捨てた整数)で求められます。p で1回、p² でさらに1回、と「何段目までわれるか」を層ごとに数えているのです。\nたとえば 50! にふくまれる 2 の個数は 25 + 12 + 6 + 3 + 1 = 47 個です。\nこの考え方は、「nCr が素数 p で何回わり切れるか」や、「n! が 12 の何乗でわり切れるか(12 = 2² × 3 なので、2 の個数の半分と 3 の個数の少ない方)」にもそのまま使えます。', key: 'n! の中の素数 p の個数は、p の倍数・p² の倍数・p³ の倍数……の個数の和。末尾の 0 の個数は 5 の個数で決まる。', ex: [{ q: '1000! を 7ᵏ でわり切れるような最大の自然数 k を求めよう。', hint: '[1000/7] + [1000/49] + [1000/343] + …', steps: ['1 から 1000 までの 7 の倍数は、1000 ÷ 7 = 142 余り 6 なので 142 個。それぞれ 7 を少なくとも1個もちます。', '49 = 7² の倍数は 1000 ÷ 49 = 20 余り 20 で 20 個。これらは 7 をもう1個ずつもつので、20 を加えます。', '343 = 7³ の倍数は 1000 ÷ 343 = 2 余り 314 で 2 個(343 と 686)。さらに1個ずつ加えます。7⁴ = 2401 は 1000 をこえるので、ここで終わりです。', '合計 142 + 20 + 2 = 164。1000! は 7¹⁶⁴ でわり切れ、7¹⁶⁵ ではわり切れません。'], a: 'k = 164', check: '小さい場合で確かめます。14! にふくまれる 7 は、7 と 14 の2個で、式でも [14/7] = 2 です。49! なら [49/7] + [49/49] = 7 + 1 = 8 で、49 = 7 × 7 が 7 を2個もつ分がきちんと数えられています。' }] },
      { h: '実戦演習:最大公約数・最小公倍数から2数を決める', t: '「2つの自然数の和が 84 で、最大公約数が 12」のような問題は、【最大公約数 G でくくった形】a = Ga′、b = Gb′ にするのが定番の戦略です。\nこのとき a′ と b′ は【互いに素】(1 以外に公約数をもたない)になります。もし公約数があれば、G よりも大きな公約数が作れてしまうからです。\nさらに、最小公倍数は L = Ga′b′、つまり【ab = GL】という関係が成り立ちます。\n落とし穴は、a′、b′ が互いに素であるという条件を忘れて、候補を多く数えすぎることです。たとえば a′ + b′ = 7 なら (1, 6)、(2, 5)、(3, 4) はすべて互いに素ですが、a′ + b′ = 8 なら (2, 6) や (4, 4) は除かなければなりません。', key: 'a = Ga′、b = Gb′(a′ と b′ は互いに素)とおく。最小公倍数は Ga′b′ で、ab = GL が成り立つ。', ex: [{ q: '和が 84、最大公約数が 12 である2つの自然数の組をすべて求めよう(小さい方を a とする)。', hint: 'a = 12a′、b = 12b′ とおくと a′ + b′ = 7。', steps: ['最大公約数が 12 なので、a = 12a′、b = 12b′(a′ と b′ は互いに素な自然数、a′ < b′)とおけます。', '和の条件から 12a′ + 12b′ = 84、つまり a′ + b′ = 7 です。', 'a′ < b′ で和が 7 になる組は (1, 6)、(2, 5)、(3, 4)。どれも互いに素なので、すべて条件を満たします(a′ = b′ にはならないことにも注意)。', '12 倍すると (a, b) = (12, 72)、(24, 60)、(36, 48) です。'], a: '(12, 72)、(24, 60)、(36, 48)', check: '互除法で確かめます。72 と 12 の最大公約数は 12、60 と 24 は 60 = 24 × 2 + 12、24 = 12 × 2 で 12、48 と 36 は 48 = 36 + 12 で 12。どれも条件どおりです。' }, { q: '最大公約数が 6、最小公倍数が 72 である2つの自然数の組をすべて求めよう(小さい方を a とする)。', hint: 'a = 6a′、b = 6b′ とすると、最小公倍数は 6a′b′。', steps: ['a = 6a′、b = 6b′(a′ と b′ は互いに素、a′ < b′)とおきます。', '最小公倍数は 6a′b′ なので、6a′b′ = 72 から a′b′ = 12 です。', '積が 12 になる組は (1, 12)、(2, 6)、(3, 4)。このうち (2, 6) は公約数 2 をもつので互いに素ではなく、除きます。', '残った (1, 12)、(3, 4) を 6 倍して、(a, b) = (6, 72)、(18, 24) です。'], a: '(6, 72)、(18, 24)', check: '(12, 36) は (2, 6) から作った組ですが、最大公約数は 12 で条件に合いません。ab = GL も確かめると、6 × 72 = 432、18 × 24 = 432、G × L = 6 × 72 = 432 で一致します。' }] }
    ],
    drill: [
      { lv: 2, q: '30! を計算したとき、末尾に 0 は何個並ぶか。', a: '7 個', exp: '末尾の 0 の個数は、30! にふくまれる 10 = 2 × 5 の個数で、2 より少ない 5 の個数で決まります。5 の倍数は 30 ÷ 5 = 6 個(5、10、15、20、25、30)、25 の倍数は 30 ÷ 25 = 1 個(25)で、25 は 5 を2個もつのでもう1個数えます。合計 6 + 1 = 7 個です。よくあるまちがいは、5 の倍数の個数 6 だけを答えて、25 = 5 × 5 の2個目を数え忘れることです。2 の個数は 15 + 7 + 3 + 1 = 26 個で、5 の個数よりずっと多いことも確かめておくと安心です。' },
      { lv: 3, q: '正の約数がちょうど 6 個である 100 以下の自然数は何個あるか。', a: '16 個', exp: '約数の個数が 6 = 6 × 1 = 3 × 2 なので、素因数分解の形は p⁵ か p²q(p、q は異なる素数)です。p⁵ の形:2⁵ = 32 だけ(3⁵ = 243 は大きすぎる)。p²q の形:p = 2 のとき 4q ≦ 100 で q は 2 以外の素数、q = 3、5、7、11、13、17、19、23 の 8 個。p = 3 のとき 9q ≦ 100 で q = 2、5、7、11 の 4 個。p = 5 のとき 25q ≦ 100 で q = 2、3 の 2 個。p = 7 のとき 49q ≦ 100 で q = 2 の 1 個。合計 1 + 8 + 4 + 2 + 1 = 16 個です。q = p の場合(p³ になり約数は 4 個)を入れないように注意しましょう。' },
      { lv: 3, q: '2つの自然数 a、b(a < b)の積が 1728、最小公倍数が 144 である。a、b を求めよう。', a: '(a, b) = (12, 144)、(36, 48)', exp: 'ab = GL なので、最大公約数は G = 1728 ÷ 144 = 12 です。a = 12a′、b = 12b′(a′ と b′ は互いに素、a′ < b′)とおくと、L = 12a′b′ = 144 から a′b′ = 12。積が 12 の組 (1, 12)、(2, 6)、(3, 4) のうち、互いに素なのは (1, 12) と (3, 4) です。よって (a, b) = (12, 144)、(36, 48)。(24, 72) は積が 1728 ですが、最大公約数が 24、最小公倍数が 72 なので条件に合いません。ab = GL を使うと、最小公倍数と積から最大公約数が先に分かるのがポイントです。' }
    ],
    faq: [
      ['末尾の 0 の個数を数えるのに、なぜ 5 だけ数えればいいの?', '末尾の 0 は 10 = 2 × 5 のペアが1組できるごとに1個増えます。n! では、2 の倍数は2つに1つ、5 の倍数は5つに1つしかないので、2 の個数は必ず 5 の個数以上になります。だから、ペアの数は少ない方の 5 の個数で決まるのです。ただし、「n! を 12 で何回われるか」のように、2 が2個ずつ必要な場合は、どちらが足りなくなるかを両方計算して確かめましょう。'],
      ['ab = GL は、3つの数でも成り立つの?', '成り立ちません。たとえば 2、4、6 では、積は 48、最大公約数は 2、最小公倍数は 12 で、2 × 12 = 24 ≠ 48 です。2つの数の場合は、素因数ごとに「小さい方の指数 + 大きい方の指数 = 2つの指数の和」となるので ab = GL が成り立ちますが、3つになると、この関係がくずれます。2つの数だけで使える関係だと覚えておきましょう。']
    ]
  });

  add('mx_h1', {
    secs: [
      { h: 'さらに深く:「すべての x で f > g」と「f の最小 > g の最大」はちがう', t: '2つの関数 f(x)、g(x) について、次の2つの条件は似ていますが、意味がちがいます。\n(i)【定義域のすべての x について f(x) > g(x)】\n(ii)【定義域のすべての x₁、x₂ について f(x₁) > g(x₂)】\n(i)は、同じ x で比べます。グラフでいえば、y = f(x) が y = g(x) よりいつも上にあることです。条件は、差 h(x) = f(x) − g(x) の最小値が正、つまり【h(x) の最小値 > 0】です。\n(ii)は、別々の x で比べます。f のどの値も、g のどの値より大きい、ということです。条件は【f(x) の最小値 > g(x) の最大値】です。\n(ii)が成り立てば(i)も成り立ちますが、逆は成り立ちません。(ii)の方がきびしい条件です。\n例:0 ≦ x ≦ 3 で、f(x) = x² − 2x + a、g(x) = −x² + 4x とします。\n(i)h(x) = 2x² − 6x + a = 2(x − 3/2)² + a − 9/2。軸 x = 3/2 は範囲の中なので、最小値は a − 9/2。条件は a > 9/2 です。\n(ii)f(x) = (x − 1)² + a − 1 の最小値は a − 1(x = 1)。g(x) = −(x − 2)² + 4 の最大値は 4(x = 2)。条件は a − 1 > 4、つまり a > 5 です。\nたしかに(ii)の方がきびしくなりました。f が最小になる x(= 1)と、g が最大になる x(= 2)がちがうので、(i)のように同じ x で比べると条件がゆるくなるのです。\n問題文の「すべての x」「すべての x₁、x₂」「ある x」などのことばを正しく読み分けることが、この型の問題で一番大切です。', key: '同じ x で比べるなら差の最小値 > 0、別々の x で比べるなら f の最小値 > g の最大値。ことばの読み分けが答えを分ける。', ex: [{ q: '0 ≦ x ≦ 2 で、f(x) = x² + a、g(x) = −x² + 2x + 3 とする。(1)すべての x について f(x) ≧ g(x) となる a の範囲、(2)すべての x₁、x₂ について f(x₁) ≧ g(x₂) となる a の範囲を求めよう。', hint: '(1)は h(x) = f(x) − g(x) の最小値。(2)は f の最小値と g の最大値。', steps: ['(1)h(x) = f(x) − g(x) = 2x² − 2x + a − 3 = 2(x − 1/2)² + a − 7/2。軸 x = 1/2 は範囲の中なので、最小値は a − 7/2 です。', 'すべての x で h(x) ≧ 0 となる条件は a − 7/2 ≧ 0、つまり a ≧ 7/2 です。', '(2)f(x) = x² + a の 0 ≦ x ≦ 2 での最小値は a(x = 0)。g(x) = −(x − 1)² + 4 の最大値は 4(x = 1)です。', '条件は a ≧ 4 です。(1)より(2)の方がきびしい条件になっています。'], a: '(1)a ≧ 7/2 (2)a ≧ 4', check: 'a = 3.7 で確かめます。(1)h(1/2) = 0.2 > 0 で成り立ちます。(2)f(0) = 3.7 と g(1) = 4 を比べると f(0) < g(1) なので成り立ちません。7/2 ≦ a < 4 の a では、(1)は成り立つが(2)は成り立たない、という差がはっきり見えます。' }] },
      { h: '実戦演習:最大値と最小値の差が与えられたとき', t: '「f(x) = x² − 2ax(0 ≦ x ≦ 2)の最大値と最小値の差が 3 のとき a を求めよ」という問題は、最大値の場合分けと最小値の場合分けを【両方】使う総合問題です。\n戦略:①最小値の場合分けの境目(軸が範囲の左・中・右:a = 0、2)と、最大値の境目(軸が範囲の真ん中:a = 1)を数直線に並べる ②境目は 0、1、2 の3つなので、4つの区間に分ける ③それぞれの区間で「最大値 − 最小値」を a の式で表し、= 3 を解く ④出てきた a が、その区間に入っているかを確かめる。\n落とし穴は④です。区間の外の解を残すと、まちがった答えになります。', key: '最大値と最小値の境目をすべて集めて区間を分ける。解いた a がその区間に入るかを必ず確かめる。', ex: [{ q: 'f(x) = x² − 2ax(0 ≦ x ≦ 2)の最大値と最小値の差が 3 となるような、定数 a の値を求めよう。', hint: 'f(x) = (x − a)² − a²。f(0) = 0、f(2) = 4 − 4a。境目は a = 0、1、2。', steps: ['f(x) = (x − a)² − a²。両端の値は f(0) = 0、f(2) = 4 − 4a です。最小値の境目は軸 a が 0、2 のとき、最大値の境目は軸が真ん中の a = 1 のときです。', 'a < 0 のとき:軸は範囲の左なので、最小 f(0) = 0、最大 f(2) = 4 − 4a。差は 4 − 4a = 3 から a = 1/4 ですが、a < 0 に入らないので不適です。', '0 ≦ a ≦ 1 のとき:最小 −a²、最大は軸から遠い右端で f(2) = 4 − 4a。差は 4 − 4a + a² = (a − 2)² = 3 から a = 2 ± √3。範囲に入るのは a = 2 − √3(約 0.27)です。', '1 ≦ a ≦ 2 のとき:最小 −a²、最大は左端で f(0) = 0。差は a² = 3 から a = √3(約 1.73)で、範囲に入ります。a > 2 のとき:最小 f(2) = 4 − 4a、最大 0 で、差 4a − 4 = 3 から a = 7/4 は a > 2 に入らず不適です。'], a: 'a = 2 − √3、√3', check: 'a = √3 のとき、最小値は f(√3) = −3、最大値は f(0) = 0(f(2) = 4 − 4√3 ≒ −2.93 より大きい)で、差は 3 です。境目 a = 1 では、どちらの式でも差は 1 になり、2つの区間の式がつながっていることも確かめられます。' }] }
    ],
    drill: [
      { lv: 2, q: '0 ≦ x ≦ 2 のすべての x₁、x₂ について、x₁² + a ≧ −x₂² + 2x₂ + 3 が成り立つような定数 a の値の範囲を求めよう。', a: 'a ≧ 4', exp: 'x₁ と x₂ は別々に動くので、「左辺の最小値 ≧ 右辺の最大値」が条件です。左辺 x₁² + a の最小値は x₁ = 0 のときの a。右辺 −x₂² + 2x₂ + 3 = −(x₂ − 1)² + 4 の最大値は x₂ = 1 のときの 4。よって a ≧ 4 です。もし同じ x で比べる「すべての x について x² + a ≧ −x² + 2x + 3」なら、差 2x² − 2x + a − 3 の最小値 a − 7/2 ≧ 0 から a ≧ 7/2 となり、条件がゆるくなります。文字が x₁、x₂ と分かれているかどうかを必ず見ましょう。' },
      { lv: 3, q: 'f(x) = x² − 2ax(0 ≦ x ≦ 1)の最大値と最小値の差が 1 となるような、定数 a の値をすべて求めよう。', a: 'a = 0、1', exp: 'f(x) = (x − a)² − a²、f(0) = 0、f(1) = 1 − 2a。境目は a = 0、1/2、1 です。a < 0:最小 0、最大 1 − 2a で差 1 − 2a = 1 から a = 0 は a < 0 に入らず不適。0 ≦ a ≦ 1/2:最小 −a²、最大 f(1) = 1 − 2a で差 (a − 1)² = 1 から a = 0、2 のうち a = 0 が適する。1/2 ≦ a ≦ 1:最小 −a²、最大 0 で差 a² = 1 から a = 1 が適する。a > 1:最小 1 − 2a、最大 0 で差 2a − 1 = 1 から a = 1 は不適。答えは a = 0、1 です。a = 0 は「a < 0」の区間では不適でも、「0 ≦ a ≦ 1/2」の区間で適するので、答えに残ります。' },
      { lv: 3, q: 'コインを5回投げるとき、表が3回以上続けて出る(表が3回以上連続する部分がある)確率を求めよう。', a: '1/4', exp: '表の連続が3回以上になる並びを、連続の始まる位置で重ならないように数えます。表表表が1〜3回目にある並びは、4、5回目が自由で 4 通り。2〜4回目で初めて始まる並びは、1回目が裏で 5回目が自由なので 2 通り。3〜5回目で初めて始まる並びは、2回目が裏で 1回目が自由なので 2 通り。合計 8 通りで、確率は 8/32 = 1/4 です。「表表表の位置3か所 × 残り4通り = 12」と数えると、表表表表のように2か所に当てはまる並びを重複して数えてしまいます。「初めて始まる位置」で分けると重なりがなくなります。' }
    ],
    faq: [
      ['場合分けの答えが、境目でつながっているか確かめるのはなぜ?', '最大値や最小値は、a を少しずつ変えると、少しずつ変わる(とびがない)からです。だから、2つの区間の式に境目の a を代入すると、同じ値になるはずです。たとえば 0 ≦ a ≦ 1 で (a − 2)²、1 ≦ a ≦ 2 で a² なら、a = 1 でどちらも 1 になります。値がずれていたら、どこかで計算をまちがえているサインです。手軽で強力な検算なので、場合分けのあとは必ずやってみましょう。'],
      ['「連続して〜回」を数えるときのコツは?', '「初めて条件を満たした位置」や「連続が始まる位置」で場合を分けると、重なりなく数えられます。また、その手前は必ず「裏」であることを使うと、数える量が減ります。回数が多いときは、「n 回目までに連続が起きていない並びの数」を表にして、1回ずつ増やしていく方法(漸化式の考え方)が確実です。']
    ]
  });

  add('hd_m1', {
    secs: [
      { h: 'さらに深く:2次方程式が整数解をもつ条件', t: '「2次方程式 x² − kx + k + 2 = 0 の2つの解がともに整数となる整数 k をすべて求めよ」のような問題は、難関大の定番です。手がかりは2つあります。\n方法1:【解と係数の関係で、積の形を作る】\n2つの解を α、β(α ≦ β)とすると、α + β = k、αβ = k + 2 です(数学Ⅱで学ぶ関係ですが、x² − kx + k + 2 = (x − α)(x − β) を展開して係数を比べれば分かります)。k を消すと αβ = α + β + 2、つまり αβ − α − β + 1 = 3 で、【(α − 1)(β − 1) = 3】という積の形になります。\nα − 1、β − 1 は整数で、積が 3 なので、(α − 1, β − 1) = (1, 3) または (−3, −1)。よって (α, β) = (2, 4)、(−2, 0) で、k = α + β = 6、−2 です。\n方法2:【判別式が平方数】\n解の公式 x = (k ± √D)/2 が整数になるには、少なくとも D = k² − 4k − 8 が【整数の2乗】でなければなりません。D = m²(m ≧ 0)とおくと (k − 2)² − m² = 12 なので、(k − 2 + m)(k − 2 − m) = 12。2つの因数は和が偶数(2(k − 2))なので、どちらも偶数で、(6, 2) か (−2, −6) です。ここから k = 6、−2 が出ます。\nどちらの方法も、最後は【積 = 整数】の形にして、約数の組で候補をしぼるのがカギです。方法1は解が直接分かり、方法2は解と係数の関係を使わずにすみます。問題によって、計算が軽い方を選びましょう。', key: '整数解の条件は、解と係数の関係で (α − p)(β − q) = 整数 の形にするか、判別式を平方数とおいて因数分解する。', ex: [{ q: '2次方程式 x² − mx + 2m = 0 の2つの解がともに整数となるような整数 m をすべて求めよう。', hint: 'α + β = m、αβ = 2m から m を消す。', steps: ['2つの解を α、β(α ≦ β)とすると、α + β = m、αβ = 2m です。', 'm を消すと αβ = 2(α + β)、つまり αβ − 2α − 2β = 0。両辺に 4 を足すと (α − 2)(β − 2) = 4 です。', 'α − 2 ≦ β − 2 で積が 4 になる整数の組は (1, 4)、(2, 2)、(−4, −1)、(−2, −2) です。', 'それぞれ (α, β) = (3, 6)、(4, 4)、(−2, 1)、(0, 0) で、m = α + β = 9、8、−1、0 です。'], a: 'm = −1、0、8、9', check: 'm = 9 なら x² − 9x + 18 = (x − 3)(x − 6)、m = 8 なら (x − 4)²、m = −1 なら x² + x − 2 = (x + 2)(x − 1)、m = 0 なら x² = 0 で、どれも整数解です。重解 (4, 4)、(0, 0) を落とさないように注意しましょう。' }] },
      { h: '実戦演習:サイコロの目を係数にした2次方程式', t: 'サイコロの目を2次方程式の係数にする問題は、確率と整数の融合問題として入試でよく出ます。\n戦略は、条件を【a と b の不等式や等式】に直し、36 通りの (a, b) を【a ごとに】数えることです。「実数解をもつ」なら判別式 D ≧ 0、「整数解をもつ」なら、解と係数の関係を使って解の組から逆に (a, b) を作る方が、もれなく数えられます。\n落とし穴は、D ≧ 0 の等号(重解)の扱いと、a、b が 1 から 6 までという範囲を忘れて、範囲外の組を数えてしまうことです。表をかいて1つずつ印をつけると確実です。', key: '条件を a、b の式にし、a の値ごとに b を数える。整数解は、解の組から (a, b) を作ると数えもれがない。', ex: [{ q: '大小2つのサイコロを投げ、大の目を a、小の目を b とする。2次方程式 x² + ax + b = 0 について、(1)実数解をもつ確率、(2)整数解をもつ確率を求めよう。', hint: '(1)a² ≧ 4b。(2)解はどちらも負の整数になる(和 −a < 0、積 b > 0)。', steps: ['(1)実数解をもつ条件は D = a² − 4b ≧ 0、つまり b ≦ a²/4 です。a = 1 なら b ≦ 1/4 で 0 個、a = 2 なら b ≦ 1 で 1 個、a = 3 なら b ≦ 2.25 で 2 個、a = 4 なら b ≦ 4 で 4 個、a = 5、6 なら 6 個ずつ。合計 19 通りで、確率は 19/36 です。', '(2)解を α、β とすると α + β = −a < 0、αβ = b > 0 なので、2つの解はどちらも負です。整数解が1つあれば、もう1つも −a − α で整数になります。そこで、α = −p、β = −q(1 ≦ p ≦ q)とおくと、a = p + q、b = pq です。', 'a ≦ 6、b ≦ 6 を満たす (p, q) は (1, 1)、(1, 2)、(1, 3)、(1, 4)、(1, 5)、(2, 2)、(2, 3) の 7 組です。(2, 4) は b = 8 で範囲外です。', 'それぞれ (a, b) = (2, 1)、(3, 2)、(4, 3)、(5, 4)、(6, 5)、(4, 4)、(5, 6) の 7 通りなので、確率は 7/36 です。'], a: '(1)19/36 (2)7/36', check: '(2)の7組は、(1)の19組にすべてふくまれているはずです。たとえば (5, 6) は 25 ≧ 24 で、たしかに D ≧ 0 です。整数解をもてば実数解をもつので、包含関係が成り立っていることが確かめになります。' }] }
    ],
    drill: [
      { lv: 2, q: '2次方程式 x² − 6x + k = 0 の2つの解がともに正の整数となるような k の値をすべて求めよう。', a: 'k = 5、8、9', exp: '2つの解を α、β(α ≦ β)とすると、α + β = 6、αβ = k です。α、β は正の整数で和が 6 なので、(α, β) = (1, 5)、(2, 4)、(3, 3) です。k = αβ は 5、8、9 です。重解 (3, 3) のとき方程式は (x − 3)² = 0 で、「2つの解」は重解として同じ値 3 を2つと考えます。問題によっては「異なる2つの解」と指定されることがあり、そのときは k = 9 を除きます。問題文の「異なる」の有無を必ず確かめましょう。' },
      { lv: 3, q: '2次方程式 x² − kx + k + 2 = 0 の2つの解がともに整数となるような整数 k をすべて求め、そのときの解を答えよう。', a: 'k = 6(解 2、4)、k = −2(解 −2、0)', exp: '2つの解を α、β(α ≦ β)とすると、α + β = k、αβ = k + 2。k を消すと αβ − α − β = 2、両辺に 1 を足して (α − 1)(β − 1) = 3 です。α − 1 ≦ β − 1 で積が 3 の整数の組は (1, 3)、(−3, −1) なので、(α, β) = (2, 4)、(−2, 0)。k = α + β = 6、−2 です。確かめると、k = 6 で x² − 6x + 8 = (x − 2)(x − 4)、k = −2 で x² + 2x = x(x + 2) です。負の約数の組 (−3, −1) を忘れると、k = −2 を落とします。積の形にしたら、正の組と負の組の両方を書き出しましょう。' },
      { lv: 3, q: 'サイコロを3回ふり、出た目を順に a、b、c とする。a ≦ b ≦ c となる確率を求めよう。', a: '7/27', exp: 'a ≦ b ≦ c となる (a, b, c) は、1〜6 の目から【重複を許して3つ選び、小さい順に並べたもの】と1対1に対応します。並べ方は1通りに決まるので、重複組合せの数を数えればよいのです。6種類から重複を許して3個選ぶ方法は、○3個と仕切り | 5本の並べ方で 8C3 = 56 通りです。全体は 6³ = 216 通りなので、確率は 56/216 = 7/27 です。a < b < c(すべて異なる)なら 6C3 = 20 通りで 20/216 = 5/54 となり、等号の有無で答えが大きく変わります。' }
    ],
    faq: [
      ['整数解の問題で、判別式と解と係数の関係、どちらを使えばいいの?', '係数に k が1次で入っているなら、解と係数の関係で k を消し、(α − p)(β − q) = 整数 の形にする方が速いことが多いです。解そのものも直接分かります。一方、k が2次で入っていたり、解と係数の関係で k がうまく消えなかったりするときは、判別式を m² とおいて因数分解します。ただし、判別式が平方数でも、解が整数になるとは限らない(分母の 2 でわれないことがある)ので、最後に解を確かめましょう。'],
      ['確率の問題で、(a, b) の組を表にするのはなぜ?', '36 通り程度なら、表にすると【もれも重なりもなく】数えられるからです。条件が「a² ≧ 4b」のような不等式でも、表の各マスに ○ をつければ、目で数を確かめられます。また、表の形(たとえば右上に ○ が集まる)から、a ごとの個数の規則に気づくこともあります。式だけで数えたときも、表で検算すると安心です。']
    ]
  });
})(WPS.LESSONS);
